-- Privacy Policy Content Seed Data
-- The published policy document for version 2026.07, one row per language.
-- GENERATED from Auth_UI/apps/accounts/src/pages/privacy/content/*.ts (the
-- offline fallback bundle) — regenerate with that script if the fallback
-- changes. After seeding, the DATABASE is authoritative: edit the content in
-- the console (Notifications -> Privacy Policy), never here.
-- Numeric disclosures are {{tokens}} interpolated from AccountDeletionSettings
-- at read time, so appsettings changes flow into the published policy.

DECLARE @SystemUserId UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000001';
DECLARE @VersionId UNIQUEIDENTIFIER = '46000000-0000-0000-0000-000000000001';

IF EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyVersions] WHERE [Id] = @VersionId)
BEGIN

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'en')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000001', @VersionId, N'en', N'{"title":"Privacy Policy","effectiveDate":"Effective 28 July 2026","versionLabel":"Version","unfilledWarning":"Draft — controller details are not filled in yet. This page must not be published until every placeholder is completed.","contactDpoLabel":"Data protection officer","contactVerbisLabel":"VERBİS registration number","contactKepLabel":"Registered e-mail (KEP)","intro":["This policy explains what personal data the [LEGAL ENTITY NAME] account service collects, why we collect it, how long we keep it, and the rights you have over it — including how to delete your account and everything attached to it.","It also serves as the disclosure required by Article 10 of Türkiye''s Personal Data Protection Law No. 6698 (KVKK) — our primary compliance framework — and is written to meet the EU/EEA General Data Protection Regulation (GDPR) and the California Consumer Privacy Act as amended (CCPA/CPRA). The controls described in this policy are available to every user, regardless of location."],"sections":[{"heading":"Data we collect","paragraphs":["We collect only what the account service needs to work. We never ask for more than that, and optional fields are clearly optional."],"bullets":["Account and profile: email address, first and last name, optional display name, optional phone number (stored encrypted), optional profile picture, preferred language, time zone and theme.","Credentials and security settings: your password (stored only as a one-way Argon2id hash — we cannot read it), optional two-factor authentication secret and recovery codes (stored encrypted), and password-change history (hashes only, to prevent reuse).","Sign-in with Google or Apple: your provider identifier, email and name as shared by the provider. For Apple, a revocation token is stored encrypted solely so we can revoke Apple''s sign-in permission when you delete your account.","Security and usage records: sign-in attempts (time, IP address, browser identifier, outcome), active sessions and tokens, and an audit log of account-related actions.","Communications: a record of the service emails we send you (verification codes, security notices, deletion confirmations). Message content that carries one-time codes or sign-in links is removed from this record as soon as the email is delivered — not even our administrators can read it."]},{"heading":"Why we process it (legal bases)","paragraphs":["Your data is collected electronically, through the forms and sign-in flows of the service itself. Each purpose rests on a legal basis under KVKK Article 5 and its GDPR Article 6 equivalent:"],"bullets":["To provide your account — authentication, sessions, profile, organization membership (necessary for the performance of a contract: KVKK Art. 5(2)(c); GDPR Art. 6(1)(b)).","To keep accounts secure — sign-in attempt records, rate limiting, session revocation, audit logging, fraud prevention (legitimate interests: KVKK Art. 5(2)(f); GDPR Art. 6(1)(f)).","To meet legal obligations — retaining minimal evidence that a deletion request was honored (KVKK Art. 5(2)(ç); GDPR Art. 6(1)(c)).","Optional data — the phone number and profile picture are processed only because you chose to provide them, and you can remove them at any time (explicit consent / açık rıza: KVKK Art. 5(1); GDPR Art. 6(1)(a))."]},{"heading":"What we do not do","paragraphs":["We do not sell your personal data, and we do not share it for cross-context behavioral advertising — in CCPA terms, no \"sale\" and no \"sharing\" has occurred in the preceding 12 months and none is planned. We do not run advertising or third-party analytics trackers in the account service, and we do not use your data for automated decisions that produce legal or similarly significant effects."]},{"heading":"Cookies and local storage","paragraphs":["The account service uses only what sign-in strictly requires: an essential session cookie that keeps you signed in across our own pages, and browser local storage that holds your session''s refresh token and your language/theme preference. There are no analytics, advertising or cross-site tracking cookies."]},{"heading":"Who we share data with","paragraphs":["We share personal data only with processors that operate the service, and only to the extent needed:"],"bullets":["Google (Sign in with Google) and Apple (Sign in with Apple) — only when you choose to sign in with them; the exchange is governed by their own privacy policies.","Our email delivery provider, [EMAIL DELIVERY PROVIDER], to send the service emails described above.","Our hosting provider, [HOSTING PROVIDER], which stores the service''s data.","Public authorities, if and only if a valid legal demand compels us."]},{"heading":"International transfers","paragraphs":["The service is hosted in [HOSTING COUNTRY]. Where personal data is transferred out of Türkiye, we do so under KVKK Article 9: an adequacy decision of the Personal Data Protection Board where one exists, and otherwise the appropriate safeguards that Article provides for (such as the Board''s standard contract, notified to the Authority as required). For data leaving the EEA or the UK we additionally rely on adequacy decisions or the European Commission''s Standard Contractual Clauses. The security measures below apply in every case."]},{"heading":"How we protect it","paragraphs":["Security is layered and applies to every account:"],"bullets":["Passwords are hashed with Argon2id; verification codes are stored only as hashes; reset links are stored only as HMAC digests.","Your phone number, two-factor secret and Apple revocation token are encrypted with AES-256-GCM under a key that is unique to your account.","All traffic is encrypted in transit (TLS). Sign-in is protected by rate limiting and account lockout; sessions can be revoked at any time and are all revoked instantly when you request deletion.","Account actions are recorded in an audit log so suspicious activity can be detected and investigated."]}],"retention":{"heading":"How long we keep data","intro":"We keep personal data no longer than the purpose requires. These periods are enforced automatically by the system, not by manual review:","columns":["Data","Kept for","What happens then"],"rows":[{"category":"Account and profile data","retention":"Until you delete your account (+ {{graceDays}}-day recovery window)","detail":"Permanently destroyed by the staged deletion process described below."},{"category":"Password hashes and two-factor secrets","retention":"Until account deletion","detail":"Stored only hashed or encrypted; destroyed with the account."},{"category":"Sessions and tokens","retention":"Until expiry or sign-out","detail":"All revoked immediately when deletion is requested."},{"category":"Sign-in attempt records (incl. IP address)","retention":"{{loginAttemptRetentionDays}} days","detail":"Purged automatically; de-identified immediately when the account is deleted."},{"category":"Security audit log","retention":"De-identified at account deletion","detail":"All personal fields are removed; the fact that a deletion was carried out (event type and timestamp only) is kept for at least 3 years as legal evidence."},{"category":"Record of sent service emails","retention":"{{outboxRetentionDays}} days","detail":"Purged automatically."},{"category":"Deletion verification codes","retention":"{{otpValidityMinutes}} minutes (code validity)","detail":"Stored only as hashes; expired entries are removed by the daily cleanup job."},{"category":"Deletion record (hashed identifiers)","retention":"Permanent","detail":"One-way HMAC digests of the deleted email and username, kept so deleted identifiers can never be re-registered by someone else. Contains no readable personal data."},{"category":"Backups","retention":"6 months at most","detail":"Backup rotation is enforced by the hosting platform''s retention configuration. Independently of it, deleting your account destroys the encryption key for your encrypted fields, making that data permanently unreadable even inside existing backups."}]},"deletion":{"heading":"Deleting your account","paragraphs":["You can request the permanent deletion of your account and personal data at any time, without contacting anyone. The request is acknowledged immediately and completed within {{graceDays}} days:"],"bullets":["Your account is deactivated at once and signed out of every device; every session, token and sign-in permission is revoked immediately.","For {{graceDays}} days you can change your mind — signing back in restores the account and cancels the deletion. You receive an email confirming each step.","After the {{graceDays}}-day window, deletion is carried out automatically and is irreversible: profile data is erased, security records are de-identified, per-account encryption keys are destroyed (crypto-shredding, covering backups), and — if you used Sign in with Apple — Apple is told to revoke the sign-in permission.","Your email address and username are never recycled: only one-way digests remain, so nobody else can ever register them."],"button":"Delete my account","signedInHint":"Signed in? You can also do this from your profile''s Account tab (Danger zone)."},"rights":[{"heading":"Your rights in Türkiye (KVKK)","paragraphs":["Under Article 11 of Law No. 6698, as the data subject (ilgili kişi) you have the right to learn whether your data is processed, to request information about that processing and its purpose, to know the domestic and foreign third parties it is transferred to, to request correction of incomplete or inaccurate data, to request deletion or destruction under Article 7, to ask that corrections and deletions be notified to recipients, to object to a result produced exclusively by automated analysis, and to claim compensation for damage caused by unlawful processing.","Applications are made to the data controller using the contact details below — in writing, via our registered e-mail (KEP) address where provided, or from an e-mail address you have previously notified to us — per the Communiqué on Application Procedures. We answer within 30 days at the latest, free of charge. If the application is rejected or unanswered, you may complain to the Personal Data Protection Board (Kişisel Verileri Koruma Kurulu)."]},{"heading":"Your rights in the EEA and the UK (GDPR)","paragraphs":["You have the right to access your data, to have it corrected, to have it erased, to restrict or object to processing, to receive a portable copy, and to withdraw consent at any time where processing is based on consent. Most of these you can exercise directly in the app (profile editing, account deletion); for the rest, contact us using the details below. You also have the right to lodge a complaint with your national supervisory authority."]},{"heading":"Your rights in California (CCPA/CPRA)","paragraphs":["You have the right to know what personal information we collect and to access it, to correct it, to delete it, and not to be discriminated against for exercising these rights. Because we do not sell or share personal information and use sensitive personal information only to provide the service, there is nothing to opt out of. We honor verified requests within 45 days. You may use an authorized agent to submit a request on your behalf."]},{"heading":"Everyone else","paragraphs":["The same controls — access, correction, deletion, and the in-app deletion flow above — are available to every user, regardless of where you live."]}],"closing":[{"heading":"Children","paragraphs":["The service is not directed at children and may not be used by anyone under 16. We do not knowingly collect children''s data; if you believe a child has created an account, contact us and we will delete it."]},{"heading":"Changes to this policy","paragraphs":["Each revision of this policy carries a version number (year.month, shown at the top). If we make material changes, we will notify you by email or an in-app notice before they take effect. Deletion requests are always honored under the terms in force when the request was made."]},{"heading":"Contact and complaints","paragraphs":["Data controller: [LEGAL ENTITY NAME], [REGISTERED ADDRESS]. Privacy contact: [PRIVACY CONTACT EMAIL]. We answer rights requests within 30 days (GDPR/KVKK) and 45 days (CCPA). If you are unsatisfied, you may complain to your supervisory authority: in the EEA/UK your national data protection authority, in Türkiye the Kişisel Verileri Koruma Kurumu, in California the California Privacy Protection Agency or Attorney General."]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: en';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'ar')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000002', @VersionId, N'ar', N'{"title":"سياسة الخصوصية وبيان الإفصاح","effectiveDate":"سارية اعتبارًا من 28 يوليو 2026","versionLabel":"الإصدار","unfilledWarning":"مسودة — لم تُستكمل بيانات المتحكم بالبيانات بعد. يجب عدم نشر هذه الصفحة قبل استكمال جميع الحقول.","contactDpoLabel":"مسؤول حماية البيانات","contactVerbisLabel":"رقم التسجيل في سجل VERBİS","contactKepLabel":"البريد الإلكتروني المسجل (KEP)","intro":["يوضح هذا البيان ما تجمعه خدمة حسابات [LEGAL ENTITY NAME] من بيانات شخصية، وأسباب جمعها، ومدة الاحتفاظ بها، وحقوقك المتعلقة بها — بما في ذلك كيفية حذف حسابك وكل ما يرتبط به.","وقد أُعدّ هذا البيان للوفاء بواجب الإفصاح المنصوص عليه في المادة العاشرة من قانون حماية البيانات الشخصية التركي رقم 6698 (KVKK) — وهو إطار الامتثال الأساسي لدينا — كما صيغ بما يلبي متطلبات اللائحة العامة لحماية البيانات في الاتحاد الأوروبي (GDPR) وقانون خصوصية المستهلك في كاليفورنيا بصيغته المعدلة (CCPA/CPRA). والضوابط الموضحة في هذا البيان متاحة لكل مستخدم أيًا كان محل إقامته."],"sections":[{"heading":"البيانات التي نجمعها","paragraphs":["لا نجمع إلا ما تحتاجه خدمة الحسابات لتعمل. ولا نطلب أبدًا أكثر من ذلك، والحقول الاختيارية اختيارية بوضوح."],"bullets":["الحساب والملف الشخصي: عنوان البريد الإلكتروني، والاسم الأول واسم العائلة، والاسم المعروض الاختياري، ورقم الهاتف الاختياري (يُخزَّن مشفرًا)، وصورة الملف الشخصي الاختيارية، واللغة المفضلة، والمنطقة الزمنية، والسمة.","بيانات الاعتماد وإعدادات الأمان: كلمة المرور (تُخزَّن فقط كملخص Argon2id أحادي الاتجاه — لا يمكننا قراءتها)، ومفتاح التحقق بخطوتين ورموز الاسترداد الاختيارية (تُخزَّن مشفرة)، وسجل تغييرات كلمة المرور (ملخصات فقط، لمنع إعادة الاستخدام).","تسجيل الدخول عبر Google أو Apple: معرّفك لدى المزود وبريدك الإلكتروني واسمك كما يشاركها المزود. وبالنسبة إلى Apple، يُخزَّن رمز إبطال مشفر لغرض وحيد هو إبطال إذن تسجيل الدخول لدى Apple عند حذف حسابك.","سجلات الأمان والاستخدام: محاولات تسجيل الدخول (الوقت، وعنوان IP، ومعرّف المتصفح، والنتيجة)، والجلسات والرموز النشطة، وسجل تدقيق للعمليات المتعلقة بالحساب.","المراسلات: سجل برسائل الخدمة التي نرسلها إليك (رموز التحقق، والإشعارات الأمنية، وتأكيدات الحذف). ويُحذف من هذا السجل محتوى الرسائل الذي يتضمن رموزًا لمرة واحدة أو روابط تسجيل دخول فور تسليم الرسالة — فلا يستطيع حتى مسؤولونا قراءته."]},{"heading":"أغراض المعالجة وأسسها القانونية","paragraphs":["تُجمَع بياناتك إلكترونيًا عبر نماذج الخدمة ومسارات تسجيل الدخول فيها. ويستند كل غرض إلى أساس قانوني بموجب المادة الخامسة من قانون KVKK وما يقابلها في المادة السادسة من لائحة GDPR:"],"bullets":["تقديم حسابك — المصادقة، والجلسات، والملف الشخصي، وعضوية المنظمات (ضرورة تنفيذ العقد: KVKK م 5/2-c؛ GDPR م 6/1-b).","حماية الحسابات — سجلات محاولات تسجيل الدخول، وتقييد المعدل، وإبطال الجلسات، وسجل التدقيق، ومنع الاحتيال (المصلحة المشروعة: KVKK م 5/2-f؛ GDPR م 6/1-f).","الوفاء بالالتزامات القانونية — الاحتفاظ بحد أدنى من الأدلة على تنفيذ طلب الحذف (KVKK م 5/2-ç؛ GDPR م 6/1-c).","البيانات الاختيارية — لا يُعالَج رقم الهاتف وصورة الملف الشخصي إلا لأنك اخترت تقديمهما، ويمكنك إزالتهما في أي وقت (الموافقة الصريحة: KVKK م 5/1؛ GDPR م 6/1-a)."]},{"heading":"ما لا نفعله","paragraphs":["لا نبيع بياناتك الشخصية، ولا نشاركها لأغراض الإعلانات السلوكية عبر السياقات — وبمصطلحات CCPA، لم يحدث أي «بيع» أو «مشاركة» خلال الاثني عشر شهرًا الماضية وليس مخططًا لأي منهما. ولا نشغّل في خدمة الحسابات أي متتبعات إعلانية أو أدوات تحليلات من أطراف ثالثة، ولا نستخدم بياناتك في قرارات آلية تُنتج آثارًا قانونية أو آثارًا مماثلة في أهميتها."]},{"heading":"ملفات تعريف الارتباط والتخزين المحلي","paragraphs":["لا تستخدم خدمة الحسابات إلا ما يتطلبه تسجيل الدخول حصرًا: ملف تعريف ارتباط أساسي للجلسة يُبقيك مسجلاً للدخول عبر صفحاتنا، وتخزين محلي في المتصفح يحمل رمز تجديد جلستك وتفضيلات اللغة والسمة. ولا توجد أي ملفات تعريف ارتباط للتحليلات أو الإعلانات أو التتبع عبر المواقع."]},{"heading":"مع من نشارك البيانات","paragraphs":["لا نشارك البيانات الشخصية إلا مع معالجي البيانات الذين يشغّلون الخدمة، وبالقدر اللازم فقط:"],"bullets":["Google (تسجيل الدخول عبر Google) وApple (تسجيل الدخول عبر Apple) — فقط عندما تختار تسجيل الدخول بهما؛ ويخضع هذا التبادل لسياسة الخصوصية الخاصة بكل مزود.","مزود إرسال البريد الإلكتروني لدينا، [EMAIL DELIVERY PROVIDER]، لإرسال رسائل الخدمة الموضحة أعلاه.","مزود الاستضافة لدينا، [HOSTING PROVIDER]، الذي يخزّن بيانات الخدمة.","السلطات العامة — فقط إذا ألزمنا بذلك طلب قانوني صحيح."]},{"heading":"نقل البيانات إلى الخارج","paragraphs":["تُستضاف الخدمة في [HOSTING COUNTRY]. وعند نقل البيانات الشخصية خارج تركيا، يجري ذلك وفق المادة التاسعة من قانون KVKK: استنادًا إلى قرار كفاية صادر عن مجلس حماية البيانات الشخصية حيثما وُجد، وإلا فاستنادًا إلى الضمانات المناسبة التي تنص عليها المادة (مثل العقد النموذجي الصادر عن المجلس، مع إخطار الهيئة حسب المقتضى). وبالنسبة إلى البيانات الخارجة من المنطقة الاقتصادية الأوروبية أو المملكة المتحدة، نستند إضافة إلى ذلك إلى قرارات الكفاية أو إلى البنود التعاقدية القياسية للمفوضية الأوروبية. وتُطبَّق التدابير الأمنية أدناه في جميع الأحوال."]},{"heading":"كيف نحمي البيانات","paragraphs":["الأمان متعدد الطبقات ويسري على كل حساب:"],"bullets":["تُلخَّص كلمات المرور بخوارزمية Argon2id؛ وتُخزَّن رموز التحقق كملخصات فقط، وروابط إعادة التعيين كملخصات HMAC فقط.","يُشفَّر رقم هاتفك ومفتاح التحقق بخطوتين ورمز إبطال Apple بخوارزمية AES-256-GCM تحت مفتاح فريد خاص بحسابك.","تُشفَّر كل حركة البيانات أثناء النقل (TLS). ويُحمى تسجيل الدخول بتقييد المعدل وقفل الحساب؛ ويمكن إبطال الجلسات في أي وقت، وتُبطَل جميعها فورًا عند طلب الحذف.","تُسجَّل عمليات الحساب في سجل تدقيق ليتسنى اكتشاف النشاط المريب والتحقيق فيه."]}],"retention":{"heading":"مدة الاحتفاظ بالبيانات","intro":"لا نحتفظ بالبيانات الشخصية لمدة تتجاوز ما يقتضيه الغرض. ويفرض النظام هذه المدد تلقائيًا، لا عبر مراجعة يدوية:","columns":["البيانات","مدة الاحتفاظ","ما يحدث بعدها"],"rows":[{"category":"بيانات الحساب والملف الشخصي","retention":"حتى حذف حسابك (+ فترة استرداد {{graceDays}} يومًا)","detail":"تُدمَّر نهائيًا عبر عملية الحذف المرحلية الموضحة أدناه."},{"category":"ملخصات كلمات المرور ومفاتيح التحقق بخطوتين","retention":"حتى حذف الحساب","detail":"تُخزَّن ملخصةً أو مشفرةً فقط؛ وتُدمَّر مع الحساب."},{"category":"الجلسات والرموز","retention":"حتى انتهاء الصلاحية أو تسجيل الخروج","detail":"تُبطَل جميعها فورًا عند طلب الحذف."},{"category":"سجلات محاولات تسجيل الدخول (بما فيها عنوان IP)","retention":"{{loginAttemptRetentionDays}} يومًا","detail":"تُحذف تلقائيًا؛ وتُجرَّد من الهوية فورًا عند حذف الحساب."},{"category":"سجل التدقيق الأمني","retention":"يُجرَّد من الهوية عند حذف الحساب","detail":"تُزال جميع الحقول الشخصية؛ ويُحتفظ بواقعة تنفيذ الحذف (نوع الحدث والطابع الزمني فقط) مدة لا تقل عن 3 سنوات كدليل قانوني."},{"category":"سجل رسائل الخدمة المرسلة","retention":"{{outboxRetentionDays}} يومًا","detail":"يُحذف تلقائيًا."},{"category":"رموز التحقق من الحذف","retention":"{{otpValidityMinutes}} دقيقة (صلاحية الرمز)","detail":"تُخزَّن كملخصات فقط؛ وتُحذف السجلات المنتهية عبر مهمة التنظيف اليومية."},{"category":"سجل الحذف (معرّفات ملخّصة)","retention":"دائم","detail":"ملخصات HMAC أحادية الاتجاه للبريد الإلكتروني واسم المستخدم المحذوفين، يُحتفظ بها حتى لا يتمكن أي شخص آخر أبدًا من إعادة تسجيلهما. لا يتضمن أي بيانات شخصية قابلة للقراءة."},{"category":"النسخ الاحتياطية","retention":"6 أشهر كحد أقصى","detail":"يُطبَّق تدوير النسخ الاحتياطية عبر إعدادات الاحتفاظ في منصة الاستضافة. وبمعزل عن ذلك، عند حذف حسابك يُدمَّر مفتاح تشفير حقولك المشفرة، فتغدو تلك البيانات غير قابلة للقراءة نهائيًا حتى داخل النسخ الاحتياطية القائمة."}]},"deletion":{"heading":"حذف حسابك","paragraphs":["يمكنك في أي وقت طلب الحذف النهائي لحسابك وبياناتك الشخصية دون الحاجة إلى التواصل مع أي جهة. يُقيَّد الطلب فورًا ويُنجَز في غضون {{graceDays}} يومًا:"],"bullets":["يُعطَّل حسابك فورًا ويُسجَّل خروجه من جميع الأجهزة؛ وتُبطَل في الحال جميع الجلسات والرموز وأذونات تسجيل الدخول.","لديك {{graceDays}} يومًا للعدول عن قرارك — فتسجيل الدخول مجددًا يستعيد الحساب ويلغي الحذف. وتصلك رسالة تأكيد بالبريد الإلكتروني في كل خطوة.","بعد انقضاء مدة الـ{{graceDays}} يومًا يُنفَّذ الحذف تلقائيًا ولا يمكن التراجع عنه: تُمحى بيانات الملف الشخصي، وتُجرَّد السجلات الأمنية من الهوية، وتُدمَّر مفاتيح التشفير الخاصة بالحساب (إتلاف تشفيري يشمل النسخ الاحتياطية)، وإذا كنت تستخدم تسجيل الدخول عبر Apple يُطلب من Apple إبطال إذن تسجيل الدخول.","لا يُعاد أبدًا استخدام بريدك الإلكتروني واسم المستخدم الخاص بك: لا يبقى سوى ملخصات أحادية الاتجاه، فلا يستطيع أي شخص آخر تسجيلهما أبدًا."],"button":"حذف حسابي","signedInHint":"هل أنت مسجل الدخول؟ يمكنك أيضًا إجراء ذلك من تبويب الحساب في ملفك الشخصي (منطقة الخطر)."},"rights":[{"heading":"حقوقك في تركيا (KVKK)","paragraphs":["بموجب المادة الحادية عشرة من القانون رقم 6698، لك بصفتك صاحب البيانات الحق في: معرفة ما إذا كانت بياناتك الشخصية تُعالَج، وطلب معلومات عن تلك المعالجة، ومعرفة غرض المعالجة وما إذا كانت البيانات تُستخدم وفقًا له، ومعرفة الأطراف الثالثة التي نُقلت إليها البيانات داخل البلاد أو خارجها، وطلب تصحيح البيانات الناقصة أو غير الصحيحة، وطلب حذفها أو إتلافها وفق المادة السابعة، وطلب إبلاغ الأطراف التي نُقلت إليها البيانات بعمليات التصحيح والحذف، والاعتراض على نتيجة تنشأ في غير مصلحتك من تحليل يُجرى حصريًا بأنظمة آلية، وطلب جبر الضرر إذا لحق بك ضرر جراء معالجة مخالفة للقانون.","تُقدَّم الطلبات إلى المتحكم بالبيانات عبر بيانات الاتصال أدناه — كتابةً، أو عبر عنوان بريدنا الإلكتروني المسجل (KEP) إن وُجد، أو من عنوان بريد إلكتروني سبق أن أبلغتنا به — وفق اللائحة التنظيمية لأصول وإجراءات التقدم بالطلبات إلى المتحكم بالبيانات. ونرد في غضون 30 يومًا على الأكثر ومجانًا. وإذا رُفض طلبك أو بقي دون رد، فلك التقدم بشكوى إلى مجلس حماية البيانات الشخصية."]},{"heading":"حقوقك في المنطقة الاقتصادية الأوروبية والمملكة المتحدة (GDPR)","paragraphs":["لك الحق في الوصول إلى بياناتك، وطلب تصحيحها، وطلب محوها، وتقييد المعالجة أو الاعتراض عليها، والحصول على نسخة قابلة للنقل، وسحب موافقتك في أي وقت متى كانت المعالجة قائمة على الموافقة. ويمكنك ممارسة معظم هذه الحقوق مباشرة داخل التطبيق (تحرير الملف الشخصي، وحذف الحساب)؛ وللباقي تواصل معنا عبر البيانات أدناه. ولك أيضًا الحق في تقديم شكوى إلى سلطة الرقابة الوطنية لديك."]},{"heading":"حقوقك في كاليفورنيا (CCPA/CPRA)","paragraphs":["لك الحق في معرفة ما نجمعه من معلومات شخصية والوصول إليها، وتصحيحها، وحذفها، وفي عدم التعرض للتمييز بسبب ممارسة هذه الحقوق. ولأننا لا نبيع المعلومات الشخصية ولا نشاركها، ولا نستخدم المعلومات الشخصية الحساسة إلا لتقديم الخدمة، فلا يوجد ما يُطلب إيقافه. ونلبي الطلبات الموثقة في غضون 45 يومًا. ويمكنك تقديم الطلب عبر وكيل مفوض ينوب عنك."]},{"heading":"سائر المستخدمين","paragraphs":["الضوابط ذاتها — الوصول والتصحيح والحذف ومسار الحذف داخل التطبيق أعلاه — متاحة لكل مستخدم أيًا كان محل إقامته."]}],"closing":[{"heading":"الأطفال","paragraphs":["الخدمة غير موجهة إلى الأطفال ولا يجوز استخدامها لمن هم دون السادسة عشرة. ولا نجمع بيانات الأطفال عن علم؛ فإذا كنت تعتقد أن طفلاً أنشأ حسابًا، فتواصل معنا وسنحذفه."]},{"heading":"التغييرات على هذه السياسة","paragraphs":["يحمل كل تنقيح لهذه السياسة رقم إصدار (سنة.شهر، يظهر أعلى الصفحة). وإذا أجرينا تغييرات جوهرية، فسنخطرك بالبريد الإلكتروني أو بإشعار داخل التطبيق قبل سريانها. وتُنفَّذ طلبات الحذف دائمًا وفق الشروط السارية وقت تقديم الطلب."]},{"heading":"التواصل والشكاوى","paragraphs":["المتحكم بالبيانات: [LEGAL ENTITY NAME]، [REGISTERED ADDRESS]. جهة التواصل بشأن الخصوصية: [PRIVACY CONTACT EMAIL]. نرد على طلبات الحقوق في غضون 30 يومًا (KVKK/GDPR) و45 يومًا (CCPA). وإذا لم تكن راضيًا عن النتيجة، فلك التقدم بشكوى إلى سلطة الرقابة المختصة: في تركيا هيئة حماية البيانات الشخصية، وفي المنطقة الاقتصادية الأوروبية والمملكة المتحدة سلطة حماية البيانات الوطنية لديك، وفي كاليفورنيا وكالة حماية خصوصية كاليفورنيا أو النائب العام."]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: ar';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'tr')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000003', @VersionId, N'tr', N'{"title":"Gizlilik Politikası ve Aydınlatma Metni","effectiveDate":"Yürürlük tarihi: 28 Temmuz 2026","versionLabel":"Sürüm","unfilledWarning":"Taslak — veri sorumlusu bilgileri henüz doldurulmamıştır. Tüm alanlar tamamlanmadan bu sayfa yayımlanmamalıdır.","contactDpoLabel":"Veri koruma görevlisi","contactVerbisLabel":"VERBİS kayıt numarası","contactKepLabel":"Kayıtlı elektronik posta (KEP)","intro":["Bu metin, [LEGAL ENTITY NAME] hesap hizmetinin hangi kişisel verileri topladığını, bunları neden işlediğini, ne kadar süreyle sakladığını ve verileriniz üzerindeki haklarınızı — hesabınızı ve hesabınıza bağlı her şeyi nasıl sileceğiniz dahil — açıklar.","Bu metin, birincil uyum çerçevemiz olan 6698 sayılı Kişisel Verilerin Korunması Kanunu''nun (KVKK) 10. maddesi uyarınca veri sorumlusunun aydınlatma yükümlülüğünü yerine getirmek üzere hazırlanmış olup ayrıca AB/AEA Genel Veri Koruma Tüzüğü (GDPR) ve değişik haliyle Kaliforniya Tüketici Gizliliği Yasası (CCPA/CPRA) gerekliliklerini karşılayacak şekilde kaleme alınmıştır. Bu metinde açıklanan kontroller, konumdan bağımsız olarak her kullanıcıya sunulur."],"sections":[{"heading":"Topladığımız veriler","paragraphs":["Yalnızca hesap hizmetinin çalışması için gereken verileri toplarız. Bundan fazlasını asla istemeyiz; isteğe bağlı alanlar açıkça isteğe bağlıdır."],"bullets":["Hesap ve profil: e-posta adresi, ad ve soyad, isteğe bağlı görünen ad, isteğe bağlı telefon numarası (şifrelenmiş olarak saklanır), isteğe bağlı profil fotoğrafı, tercih edilen dil, saat dilimi ve tema.","Kimlik bilgileri ve güvenlik ayarları: parolanız (yalnızca tek yönlü Argon2id özeti olarak saklanır — parolanızı okuyamayız), isteğe bağlı iki adımlı doğrulama anahtarı ve kurtarma kodları (şifrelenmiş olarak saklanır) ile parola değişiklik geçmişi (yeniden kullanımı önlemek için, yalnızca özet olarak).","Google veya Apple ile oturum açma: sağlayıcının paylaştığı kimlik tanımlayıcınız, e-posta adresiniz ve adınız. Apple için, yalnızca hesabınızı sildiğinizde Apple''ın oturum açma iznini iptal edebilmemiz amacıyla şifrelenmiş bir iptal belirteci saklanır.","Güvenlik ve kullanım kayıtları: oturum açma denemeleri (zaman, IP adresi, tarayıcı tanımlayıcısı, sonuç), etkin oturumlar ve belirteçler ile hesapla ilgili işlemlerin denetim günlüğü.","İletişim: size gönderdiğimiz hizmet e-postalarının kaydı (doğrulama kodları, güvenlik bildirimleri, silme onayları). Tek kullanımlık kod veya oturum açma bağlantısı içeren ileti içeriği, e-posta teslim edilir edilmez bu kayıttan silinir — yöneticilerimiz dahi okuyamaz."]},{"heading":"İşleme amaçları ve hukuki sebepler","paragraphs":["Verileriniz, hizmetin form ve oturum açma akışları üzerinden elektronik ortamda toplanır. Her amaç, KVKK''nın 5. maddesindeki bir hukuki sebebe ve GDPR''ın 6. maddesindeki karşılığına dayanır:"],"bullets":["Hesabınızı sunmak — kimlik doğrulama, oturumlar, profil, organizasyon üyeliği (sözleşmenin ifası için gerekli olması: KVKK m. 5/2-c; GDPR m. 6/1-b).","Hesapları güvende tutmak — oturum açma denemesi kayıtları, hız sınırlama, oturum iptali, denetim günlüğü, dolandırıcılığın önlenmesi (meşru menfaat: KVKK m. 5/2-f; GDPR m. 6/1-f).","Hukuki yükümlülükleri yerine getirmek — bir silme talebinin yerine getirildiğine dair asgari kanıtın saklanması (KVKK m. 5/2-ç; GDPR m. 6/1-c).","İsteğe bağlı veriler — telefon numarası ve profil fotoğrafı yalnızca siz sağlamayı seçtiğiniz için işlenir ve bunları dilediğiniz an kaldırabilirsiniz (açık rıza: KVKK m. 5/1; GDPR m. 6/1-a)."]},{"heading":"Yapmadıklarımız","paragraphs":["Kişisel verilerinizi satmayız ve bağlamlar arası davranışsal reklamcılık için paylaşmayız — CCPA terimleriyle, son 12 ayda hiçbir \"satış\" veya \"paylaşım\" gerçekleşmemiştir ve planlanmamaktadır. Hesap hizmetinde reklam veya üçüncü taraf analitik izleyicileri çalıştırmayız; verilerinizi, hukuki ya da benzer ölçüde önemli sonuçlar doğuran otomatik kararlar için kullanmayız."]},{"heading":"Çerezler ve yerel depolama","paragraphs":["Hesap hizmeti yalnızca oturum açmanın kesin olarak gerektirdiğini kullanır: kendi sayfalarımız arasında oturumunuzu koruyan zorunlu bir oturum çerezi ile oturum yenileme belirtecinizi ve dil/tema tercihlerinizi tutan tarayıcı yerel depolaması. Analitik, reklam veya siteler arası izleme çerezi yoktur."]},{"heading":"Verileri kimlerle paylaşırız","paragraphs":["Kişisel verileri yalnızca hizmeti işleten veri işleyenlerle ve yalnızca gerektiği ölçüde paylaşırız:"],"bullets":["Google (Google ile oturum açma) ve Apple (Apple ile oturum açma) — yalnızca onlarla oturum açmayı seçtiğinizde; bu alışveriş, ilgili sağlayıcının kendi gizlilik politikasına tabidir.","E-posta gönderim sağlayıcımız [EMAIL DELIVERY PROVIDER] — yukarıda açıklanan hizmet e-postalarını göndermek için.","Barındırma sağlayıcımız [HOSTING PROVIDER] — hizmetin verilerini saklar.","Kamu makamları — yalnızca geçerli bir hukuki talep bizi buna zorlarsa."]},{"heading":"Yurt dışına aktarım","paragraphs":["Hizmet [HOSTING COUNTRY] ülkesinde barındırılmaktadır. Kişisel verilerin Türkiye dışına aktarılması hâlinde bu aktarım KVKK''nın 9. maddesi kapsamında yapılır: Kişisel Verileri Koruma Kurulunca yeterlilik kararı bulunan hâllerde bu karara, bulunmayan hâllerde ise maddenin öngördüğü uygun güvencelere (Kuruma bildirilmesi kaydıyla Kurulca ilan edilen standart sözleşme gibi) dayanırız. AEA veya Birleşik Krallık''tan çıkan veriler için ayrıca yeterlilik kararlarına veya Avrupa Komisyonu''nun Standart Sözleşme Maddelerine dayanırız. Aşağıdaki güvenlik önlemleri her durumda uygulanır."]},{"heading":"Verileri nasıl koruruz","paragraphs":["Güvenlik katmanlıdır ve her hesap için geçerlidir:"],"bullets":["Parolalar Argon2id ile özetlenir; doğrulama kodları yalnızca özet olarak, sıfırlama bağlantıları yalnızca HMAC özeti olarak saklanır.","Telefon numaranız, iki adımlı doğrulama anahtarınız ve Apple iptal belirteciniz, hesabınıza özgü bir anahtar altında AES-256-GCM ile şifrelenir.","Tüm trafik aktarım sırasında şifrelenir (TLS). Oturum açma, hız sınırlama ve hesap kilitleme ile korunur; oturumlar her an iptal edilebilir ve silme talebinde bulunduğunuzda tamamı derhâl iptal edilir.","Hesap işlemleri, şüpheli etkinliğin tespit edilip incelenebilmesi için denetim günlüğüne kaydedilir."]}],"retention":{"heading":"Verileri ne kadar saklarız","intro":"Kişisel verileri amacın gerektirdiğinden daha uzun süre saklamayız. Bu süreler elle inceleme ile değil, sistem tarafından otomatik olarak uygulanır:","columns":["Veri","Saklama süresi","Süre sonunda"],"rows":[{"category":"Hesap ve profil verileri","retention":"Hesabınızı silene kadar (+ {{graceDays}} günlük kurtarma süresi)","detail":"Aşağıda açıklanan aşamalı silme süreciyle kalıcı olarak yok edilir."},{"category":"Parola özetleri ve iki adımlı doğrulama anahtarları","retention":"Hesap silinene kadar","detail":"Yalnızca özet veya şifrelenmiş olarak saklanır; hesapla birlikte yok edilir."},{"category":"Oturumlar ve belirteçler","retention":"Süresi dolana veya oturum kapatılana kadar","detail":"Silme talep edildiğinde tamamı derhâl iptal edilir."},{"category":"Oturum açma denemesi kayıtları (IP adresi dahil)","retention":"{{loginAttemptRetentionDays}} gün","detail":"Otomatik olarak silinir; hesap silindiğinde derhâl kimliksizleştirilir."},{"category":"Güvenlik denetim günlüğü","retention":"Hesap silindiğinde kimliksizleştirilir","detail":"Tüm kişisel alanlar kaldırılır; silme işleminin gerçekleştirildiği bilgisi (yalnızca olay türü ve zaman damgası) hukuki kanıt olarak en az 3 yıl saklanır."},{"category":"Gönderilen hizmet e-postalarının kaydı","retention":"{{outboxRetentionDays}} gün","detail":"Otomatik olarak silinir."},{"category":"Silme doğrulama kodları","retention":"{{otpValidityMinutes}} dakika (kod geçerliliği)","detail":"Yalnızca özet olarak saklanır; süresi dolan kayıtlar günlük temizlik işiyle silinir."},{"category":"Silme kaydı (özetlenmiş tanımlayıcılar)","retention":"Kalıcı","detail":"Silinen e-posta ve kullanıcı adının tek yönlü HMAC özetleri; silinen tanımlayıcıların bir başkası tarafından asla yeniden kaydedilememesi için tutulur. Okunabilir hiçbir kişisel veri içermez."},{"category":"Yedekler","retention":"En fazla 6 ay","detail":"Yedek döngüsü, barındırma platformunun saklama yapılandırmasıyla uygulanır. Bundan bağımsız olarak, hesabınız silindiğinde şifrelenmiş alanlarınızın şifreleme anahtarı yok edilir; bu sayede söz konusu veriler mevcut yedeklerin içinde bile kalıcı olarak okunamaz hâle gelir."}]},"deletion":{"heading":"Hesabınızı silme","paragraphs":["Hesabınızın ve kişisel verilerinizin kalıcı olarak silinmesini, kimseyle iletişime geçmeden, dilediğiniz an talep edebilirsiniz. Talep derhâl kayda alınır ve en geç {{graceDays}} gün içinde tamamlanır:"],"bullets":["Hesabınız derhâl devre dışı bırakılır ve tüm cihazlarda oturumlar kapatılır; tüm oturumlar, belirteçler ve oturum açma izinleri anında iptal edilir.","{{graceDays}} gün boyunca fikrinizi değiştirebilirsiniz — yeniden oturum açmak hesabı geri yükler ve silmeyi iptal eder. Her adımda onay e-postası alırsınız.","{{graceDays}} günlük sürenin ardından silme otomatik olarak gerçekleştirilir ve geri alınamaz: profil verileri silinir, güvenlik kayıtları kimliksizleştirilir, hesaba özgü şifreleme anahtarları yok edilir (yedekleri de kapsayan kriptografik imha) ve — Apple ile oturum açtıysanız — Apple''a oturum açma iznini iptal etmesi bildirilir.","E-posta adresiniz ve kullanıcı adınız asla yeniden kullanıma açılmaz: geriye yalnızca tek yönlü özetler kalır; böylece bunları bir başkası asla kaydedemez."],"button":"Hesabımı sil","signedInHint":"Oturum açtınız mı? Bunu profilinizin Hesap sekmesinden (Tehlikeli bölge) de yapabilirsiniz."},"rights":[{"heading":"Türkiye''deki haklarınız (KVKK)","paragraphs":["6698 sayılı Kanun''un 11. maddesi uyarınca ilgili kişi olarak; kişisel verilerinizin işlenip işlenmediğini öğrenme, işlenmişse buna ilişkin bilgi talep etme, işlenme amacını ve amacına uygun kullanılıp kullanılmadığını öğrenme, yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri bilme, eksik veya yanlış işlenmişse düzeltilmesini isteme, 7. madde çerçevesinde silinmesini veya yok edilmesini isteme, düzeltme ve silme işlemlerinin aktarıldığı üçüncü kişilere bildirilmesini isteme, münhasıran otomatik sistemlerle analiz edilmesi suretiyle aleyhinize bir sonucun ortaya çıkmasına itiraz etme ve kanuna aykırı işleme sebebiyle zarara uğramanız hâlinde zararın giderilmesini talep etme haklarına sahipsiniz.","Başvurular, Veri Sorumlusuna Başvuru Usul ve Esasları Hakkında Tebliğ uyarınca aşağıdaki iletişim bilgileri üzerinden — yazılı olarak, varsa kayıtlı elektronik posta (KEP) adresimiz aracılığıyla veya bize daha önce bildirdiğiniz e-posta adresinizden — yapılabilir. Başvurular en geç 30 gün içinde ve ücretsiz olarak sonuçlandırılır. Başvurunuzun reddedilmesi veya yanıtsız kalması hâlinde Kişisel Verileri Koruma Kurulu''na şikâyette bulunabilirsiniz."]},{"heading":"AEA ve Birleşik Krallık''taki haklarınız (GDPR)","paragraphs":["Verilerinize erişme, düzeltilmesini isteme, silinmesini isteme, işlemeyi kısıtlama veya işlemeye itiraz etme, taşınabilir bir kopyasını alma ve rızaya dayalı işlemede rızanızı dilediğiniz an geri çekme hakkınız vardır. Bunların çoğunu doğrudan uygulama içinde kullanabilirsiniz (profil düzenleme, hesap silme); geri kalanı için aşağıdaki bilgilerden bize ulaşın. Ayrıca ulusal denetim makamınıza şikâyette bulunma hakkınız vardır."]},{"heading":"Kaliforniya''daki haklarınız (CCPA/CPRA)","paragraphs":["Hangi kişisel bilgileri topladığımızı öğrenme ve bunlara erişme, düzeltme, silme ve bu hakları kullandığınız için ayrımcılığa uğramama hakkınız vardır. Kişisel bilgileri satmadığımız veya paylaşmadığımız ve hassas kişisel bilgileri yalnızca hizmeti sunmak için kullandığımız için vazgeçilecek bir işlem yoktur. Doğrulanmış talepleri 45 gün içinde yerine getiririz. Talebinizi sizin adınıza yetkili bir temsilci aracılığıyla da iletebilirsiniz."]},{"heading":"Diğer tüm kullanıcılar","paragraphs":["Aynı kontroller — erişim, düzeltme, silme ve yukarıdaki uygulama içi silme akışı — nerede yaşarsanız yaşayın her kullanıcıya sunulur."]}],"closing":[{"heading":"Çocuklar","paragraphs":["Hizmet çocuklara yönelik değildir ve 16 yaşından küçükler tarafından kullanılamaz. Çocuklara ait verileri bilerek toplamayız; bir çocuğun hesap oluşturduğunu düşünüyorsanız bize bildirin, hesabı sileriz."]},{"heading":"Bu politikadaki değişiklikler","paragraphs":["Bu politikanın her revizyonu bir sürüm numarası taşır (yıl.ay, sayfanın başında gösterilir). Önemli değişiklikler yapmamız hâlinde, yürürlüğe girmeden önce sizi e-posta veya uygulama içi bildirimle bilgilendiririz. Silme talepleri her zaman, talebin yapıldığı tarihte yürürlükte olan koşullara göre yerine getirilir."]},{"heading":"İletişim ve şikâyet","paragraphs":["Veri sorumlusu: [LEGAL ENTITY NAME], [REGISTERED ADDRESS]. Gizlilik iletişimi: [PRIVACY CONTACT EMAIL]. Hak taleplerini KVKK/GDPR kapsamında 30 gün, CCPA kapsamında 45 gün içinde yanıtlarız. Sonuçtan memnun kalmazsanız denetim makamına şikâyette bulunabilirsiniz: Türkiye''de Kişisel Verileri Koruma Kurumu, AEA/Birleşik Krallık''ta ulusal veri koruma makamınız, Kaliforniya''da California Privacy Protection Agency veya Başsavcılık."]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: tr';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'fr')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000004', @VersionId, N'fr', N'{"title":"Politique de confidentialité","effectiveDate":"En vigueur au 28 juillet 2026","versionLabel":"Version","unfilledWarning":"Brouillon — les coordonnées du responsable du traitement ne sont pas encore renseignées. Cette page ne doit pas être publiée avant que tous les champs soient complétés.","contactDpoLabel":"Délégué à la protection des données","contactVerbisLabel":"Numéro d''enregistrement VERBİS","contactKepLabel":"Courriel enregistré (KEP)","intro":["Cette politique explique quelles données personnelles le service de comptes de [LEGAL ENTITY NAME] collecte, pourquoi nous les collectons, combien de temps nous les conservons et les droits dont vous disposez — y compris la manière de supprimer votre compte et tout ce qui s''y rattache.","Elle vaut également information au titre de l''article 10 de la loi turque n° 6698 sur la protection des données personnelles (KVKK) — notre cadre de conformité principal — et est rédigée pour satisfaire au Règlement général sur la protection des données de l''UE/EEE (RGPD) ainsi qu''au California Consumer Privacy Act tel que modifié (CCPA/CPRA). Les contrôles décrits dans cette politique sont offerts à chaque utilisateur, quel que soit son lieu de résidence."],"sections":[{"heading":"Les données que nous collectons","paragraphs":["Nous ne collectons que ce dont le service de comptes a besoin pour fonctionner. Nous ne demandons jamais davantage, et les champs facultatifs sont clairement facultatifs."],"bullets":["Compte et profil : adresse e-mail, prénom et nom, nom d''affichage facultatif, numéro de téléphone facultatif (stocké chiffré), photo de profil facultative, langue préférée, fuseau horaire et thème.","Identifiants et paramètres de sécurité : votre mot de passe (stocké uniquement sous forme d''empreinte Argon2id à sens unique — nous ne pouvons pas le lire), le secret d''authentification à deux facteurs et les codes de récupération facultatifs (stockés chiffrés), et l''historique des changements de mot de passe (empreintes uniquement, pour empêcher la réutilisation).","Connexion avec Google ou Apple : votre identifiant, votre e-mail et votre nom tels que partagés par le fournisseur. Pour Apple, un jeton de révocation est stocké chiffré dans le seul but de révoquer l''autorisation de connexion Apple lorsque vous supprimez votre compte.","Journaux de sécurité et d''utilisation : tentatives de connexion (heure, adresse IP, identifiant du navigateur, résultat), sessions et jetons actifs, et un journal d''audit des actions liées au compte.","Communications : une trace des e-mails de service que nous vous envoyons (codes de vérification, avis de sécurité, confirmations de suppression). Le contenu des messages porteurs de codes à usage unique ou de liens de connexion est retiré de cette trace dès la remise de l''e-mail — même nos administrateurs ne peuvent pas le lire."]},{"heading":"Pourquoi nous les traitons (bases légales)","paragraphs":["Vos données sont collectées par voie électronique, via les formulaires et les parcours de connexion du service. Chaque finalité repose sur une base légale au titre de l''article 5 de la KVKK et de son équivalent à l''article 6 du RGPD :"],"bullets":["Fournir votre compte — authentification, sessions, profil, appartenance aux organisations (nécessité contractuelle : KVKK art. 5/2-c ; RGPD art. 6(1)(b)).","Sécuriser les comptes — journaux de tentatives de connexion, limitation de débit, révocation de sessions, journal d''audit, prévention de la fraude (intérêts légitimes : KVKK art. 5/2-f ; RGPD art. 6(1)(f)).","Respecter nos obligations légales — conserver la preuve minimale qu''une demande de suppression a été honorée (KVKK art. 5/2-ç ; RGPD art. 6(1)(c)).","Données facultatives — le numéro de téléphone et la photo de profil ne sont traités que parce que vous avez choisi de les fournir, et vous pouvez les retirer à tout moment (consentement explicite : KVKK art. 5/1 ; RGPD art. 6(1)(a))."]},{"heading":"Ce que nous ne faisons pas","paragraphs":["Nous ne vendons pas vos données personnelles et ne les partageons pas à des fins de publicité comportementale intercontexte — au sens du CCPA, aucune « vente » ni aucun « partage » n''a eu lieu au cours des 12 derniers mois et aucun n''est prévu. Le service de comptes n''embarque aucun traceur publicitaire ni outil d''analyse tiers, et vos données ne servent à aucune décision automatisée produisant des effets juridiques ou d''importance similaire."]},{"heading":"Cookies et stockage local","paragraphs":["Le service de comptes n''utilise que ce que la connexion exige strictement : un cookie de session essentiel qui vous maintient connecté sur nos propres pages, et le stockage local du navigateur qui contient le jeton de renouvellement de votre session ainsi que vos préférences de langue et de thème. Il n''y a aucun cookie d''analyse, de publicité ou de suivi intersite."]},{"heading":"Avec qui nous partageons les données","paragraphs":["Nous ne partageons les données personnelles qu''avec les sous-traitants qui font fonctionner le service, et seulement dans la mesure nécessaire :"],"bullets":["Google (connexion avec Google) et Apple (connexion avec Apple) — uniquement lorsque vous choisissez de vous connecter avec eux ; l''échange est régi par leurs propres politiques de confidentialité.","Notre fournisseur d''envoi d''e-mails, [EMAIL DELIVERY PROVIDER], pour envoyer les e-mails de service décrits ci-dessus.","Notre hébergeur, [HOSTING PROVIDER], qui stocke les données du service.","Les autorités publiques, si et seulement si une demande légale valable nous y contraint."]},{"heading":"Transferts internationaux","paragraphs":["Le service est hébergé en/au [HOSTING COUNTRY]. Lorsque des données personnelles quittent la Türkiye, le transfert s''effectue au titre de l''article 9 de la KVKK : une décision d''adéquation du Conseil de protection des données personnelles lorsqu''elle existe, sinon les garanties appropriées prévues par cet article (comme le contrat type du Conseil, notifié à l''Autorité comme requis). Pour les données quittant l''EEE ou le Royaume-Uni, nous nous appuyons en outre sur des décisions d''adéquation ou sur les clauses contractuelles types de la Commission européenne. Les mesures de sécurité ci-dessous s''appliquent dans tous les cas."]},{"heading":"Comment nous les protégeons","paragraphs":["La sécurité est en couches et s''applique à chaque compte :"],"bullets":["Les mots de passe sont hachés avec Argon2id ; les codes de vérification ne sont stockés que sous forme d''empreintes ; les liens de réinitialisation uniquement sous forme de condensats HMAC.","Votre numéro de téléphone, votre secret à deux facteurs et le jeton de révocation Apple sont chiffrés en AES-256-GCM sous une clé propre à votre compte.","Tout le trafic est chiffré en transit (TLS). La connexion est protégée par la limitation de débit et le verrouillage de compte ; les sessions peuvent être révoquées à tout moment et le sont toutes instantanément lorsque vous demandez la suppression.","Les actions du compte sont consignées dans un journal d''audit afin de détecter et d''examiner toute activité suspecte."]}],"retention":{"heading":"Durées de conservation","intro":"Nous ne conservons pas les données personnelles plus longtemps que la finalité ne l''exige. Ces durées sont appliquées automatiquement par le système, sans intervention manuelle :","columns":["Données","Durée","Ce qui se passe ensuite"],"rows":[{"category":"Données de compte et de profil","retention":"Jusqu''à la suppression de votre compte (+ {{graceDays}} jours de rétractation)","detail":"Détruites définitivement par le processus de suppression par étapes décrit ci-dessous."},{"category":"Empreintes de mots de passe et secrets à deux facteurs","retention":"Jusqu''à la suppression du compte","detail":"Stockés uniquement hachés ou chiffrés ; détruits avec le compte."},{"category":"Sessions et jetons","retention":"Jusqu''à expiration ou déconnexion","detail":"Tous révoqués immédiatement lorsque la suppression est demandée."},{"category":"Journaux de tentatives de connexion (adresse IP incluse)","retention":"{{loginAttemptRetentionDays}} jours","detail":"Purgés automatiquement ; anonymisés immédiatement à la suppression du compte."},{"category":"Journal d''audit de sécurité","retention":"Anonymisé à la suppression du compte","detail":"Tous les champs personnels sont retirés ; le fait qu''une suppression a été exécutée (type d''événement et horodatage uniquement) est conservé au moins 3 ans comme preuve légale."},{"category":"Trace des e-mails de service envoyés","retention":"{{outboxRetentionDays}} jours","detail":"Purgée automatiquement."},{"category":"Codes de vérification de suppression","retention":"{{otpValidityMinutes}} minutes (validité du code)","detail":"Stockés uniquement sous forme d''empreintes ; les entrées expirées sont supprimées par le nettoyage quotidien."},{"category":"Trace de suppression (identifiants hachés)","retention":"Permanente","detail":"Condensats HMAC à sens unique de l''e-mail et du nom d''utilisateur supprimés, conservés pour que ces identifiants ne puissent jamais être réenregistrés par quelqu''un d''autre. Ne contient aucune donnée personnelle lisible."},{"category":"Sauvegardes","retention":"6 mois au plus","detail":"La rotation des sauvegardes est appliquée par la configuration de rétention de la plateforme d''hébergement. Indépendamment de cela, la suppression du compte détruit la clé de chiffrement de vos champs chiffrés, rendant ces données définitivement illisibles, même dans les sauvegardes existantes."}]},"deletion":{"heading":"Supprimer votre compte","paragraphs":["Vous pouvez demander à tout moment la suppression définitive de votre compte et de vos données personnelles, sans contacter personne. La demande est enregistrée immédiatement et exécutée sous {{graceDays}} jours :"],"bullets":["Votre compte est désactivé sur-le-champ et déconnecté de tous les appareils ; toutes les sessions, tous les jetons et toutes les autorisations de connexion sont révoqués immédiatement.","Pendant {{graceDays}} jours, vous pouvez changer d''avis — vous reconnecter restaure le compte et annule la suppression. Vous recevez un e-mail de confirmation à chaque étape.","Passé ce délai de {{graceDays}} jours, la suppression s''exécute automatiquement et est irréversible : les données de profil sont effacées, les journaux de sécurité sont anonymisés, les clés de chiffrement propres au compte sont détruites (destruction cryptographique, couvrant les sauvegardes), et — si vous utilisiez la connexion avec Apple — Apple est invité à révoquer l''autorisation de connexion.","Votre adresse e-mail et votre nom d''utilisateur ne sont jamais recyclés : seuls des condensats à sens unique subsistent, si bien que personne d''autre ne pourra jamais les enregistrer."],"button":"Supprimer mon compte","signedInHint":"Connecté ? Vous pouvez aussi le faire depuis l''onglet Compte de votre profil (Zone de danger)."},"rights":[{"heading":"Vos droits en Türkiye (KVKK)","paragraphs":["En vertu de l''article 11 de la loi n° 6698, en tant que personne concernée vous avez le droit de savoir si vos données sont traitées, de demander des informations sur ce traitement et sa finalité, de connaître les tiers, en Türkiye ou à l''étranger, auxquels elles sont transférées, de demander la rectification de données incomplètes ou inexactes, d''en demander la suppression ou la destruction au titre de l''article 7, de demander que rectifications et suppressions soient notifiées aux destinataires, de vous opposer à un résultat produit exclusivement par une analyse automatisée, et de demander réparation du préjudice causé par un traitement illicite.","Les demandes s''adressent au responsable du traitement via les coordonnées ci-dessous — par écrit, via notre adresse de courriel enregistré (KEP) lorsqu''elle est fournie, ou depuis une adresse e-mail que vous nous avez préalablement déclarée — conformément au communiqué sur les modalités de demande. Nous répondons sous 30 jours au plus tard, gratuitement. En cas de rejet ou d''absence de réponse, vous pouvez saisir le Conseil de protection des données personnelles."]},{"heading":"Vos droits dans l''EEE et au Royaume-Uni (RGPD)","paragraphs":["Vous avez le droit d''accéder à vos données, de les faire rectifier, de les faire effacer, de restreindre le traitement ou de vous y opposer, d''en recevoir une copie portable, et de retirer votre consentement à tout moment lorsque le traitement repose sur le consentement. Vous pouvez exercer la plupart de ces droits directement dans l''application (édition du profil, suppression du compte) ; pour le reste, contactez-nous aux coordonnées ci-dessous. Vous avez également le droit d''introduire une réclamation auprès de votre autorité de contrôle nationale."]},{"heading":"Vos droits en Californie (CCPA/CPRA)","paragraphs":["Vous avez le droit de savoir quelles informations personnelles nous collectons et d''y accéder, de les corriger, de les supprimer, et de ne subir aucune discrimination pour avoir exercé ces droits. Comme nous ne vendons ni ne partageons d''informations personnelles et n''utilisons les informations personnelles sensibles que pour fournir le service, il n''y a rien à refuser. Nous honorons les demandes vérifiées sous 45 jours. Vous pouvez passer par un agent autorisé pour soumettre une demande en votre nom."]},{"heading":"Tous les autres utilisateurs","paragraphs":["Les mêmes contrôles — accès, rectification, suppression et le parcours de suppression dans l''application décrit ci-dessus — sont offerts à chaque utilisateur, où que vous viviez."]}],"closing":[{"heading":"Enfants","paragraphs":["Le service ne s''adresse pas aux enfants et ne peut pas être utilisé par des personnes de moins de 16 ans. Nous ne collectons pas sciemment de données d''enfants ; si vous pensez qu''un enfant a créé un compte, contactez-nous et nous le supprimerons."]},{"heading":"Modifications de cette politique","paragraphs":["Chaque révision de cette politique porte un numéro de version (année.mois, affiché en haut de page). En cas de changement substantiel, nous vous préviendrons par e-mail ou par un avis dans l''application avant son entrée en vigueur. Les demandes de suppression sont toujours honorées selon les conditions en vigueur au moment de la demande."]},{"heading":"Contact et réclamations","paragraphs":["Responsable du traitement : [LEGAL ENTITY NAME], [REGISTERED ADDRESS]. Contact confidentialité : [PRIVACY CONTACT EMAIL]. Nous répondons aux demandes d''exercice de droits sous 30 jours (KVKK/RGPD) et 45 jours (CCPA). Si la réponse ne vous satisfait pas, vous pouvez saisir l''autorité de contrôle compétente : en Türkiye l''Autorité de protection des données personnelles, dans l''EEE/au Royaume-Uni votre autorité nationale de protection des données, en Californie la California Privacy Protection Agency ou le procureur général."]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: fr';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'zh')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000005', @VersionId, N'zh', N'{"title":"隐私政策","effectiveDate":"自 2026 年 7 月 28 日起生效","versionLabel":"版本","unfilledWarning":"草稿——数据控制者信息尚未填写。在所有占位内容完成之前，不得发布本页面。","contactDpoLabel":"数据保护官","contactVerbisLabel":"VERBİS 登记号","contactKepLabel":"注册电子邮箱（KEP）","intro":["本政策说明 [LEGAL ENTITY NAME] 账户服务收集哪些个人数据、收集原因、保存期限，以及您对这些数据享有的权利——包括如何删除您的账户及其所有关联数据。","本政策同时履行土耳其第 6698 号《个人数据保护法》（KVKK，我们的首要合规框架）第 10 条规定的告知义务，并按照欧盟/欧洲经济区《通用数据保护条例》（GDPR）及经修订的《加州消费者隐私法》（CCPA/CPRA）的要求撰写。本政策所述的各项控制权面向每一位用户提供，与所在地无关。"],"sections":[{"heading":"我们收集的数据","paragraphs":["我们只收集账户服务运行所必需的数据，绝不索取更多；可选字段均明确标注为可选。"],"bullets":["账户与个人资料：电子邮箱地址、姓名、可选的显示名称、可选的电话号码（加密存储）、可选的头像、首选语言、时区和主题。","凭据与安全设置：您的密码（仅以单向 Argon2id 哈希存储——我们无法读取）、可选的两步验证密钥和恢复码（加密存储），以及密码变更历史（仅存哈希，用于防止重复使用）。","通过 Google 或 Apple 登录：由提供方共享的您的标识符、邮箱和姓名。对于 Apple，我们加密存储一个撤销令牌，其唯一用途是在您删除账户时撤销 Apple 的登录授权。","安全与使用记录：登录尝试（时间、IP 地址、浏览器标识、结果）、活动会话与令牌，以及账户相关操作的审计日志。","通信：我们向您发送的服务邮件的记录（验证码、安全通知、删除确认）。含一次性验证码或登录链接的邮件内容会在送达后立即从该记录中删除——连我们的管理员也无法读取。"]},{"heading":"处理目的与法律依据","paragraphs":["您的数据通过服务本身的表单和登录流程以电子方式收集。每项目的均基于 KVKK 第 5 条及 GDPR 第 6 条相应条款的法律依据："],"bullets":["提供您的账户——身份验证、会话、个人资料、组织成员资格（履行合同所必需：KVKK 第 5/2-c 条；GDPR 第 6(1)(b) 条）。","保障账户安全——登录尝试记录、速率限制、会话撤销、审计日志、欺诈防范（正当利益：KVKK 第 5/2-f 条；GDPR 第 6(1)(f) 条）。","履行法律义务——保留删除请求已被执行的最少证据（KVKK 第 5/2-ç 条；GDPR 第 6(1)(c) 条）。","可选数据——电话号码和头像仅因您选择提供而被处理，您可以随时移除（明示同意：KVKK 第 5/1 条；GDPR 第 6(1)(a) 条）。"]},{"heading":"我们不会做的事","paragraphs":["我们不出售您的个人数据，也不为跨情境行为广告而共享数据——按 CCPA 的定义，过去 12 个月内未发生任何“出售”或“共享”，也无此计划。账户服务中不运行广告或第三方分析跟踪器，也不会将您的数据用于产生法律效力或类似重大影响的自动化决策。"]},{"heading":"Cookie 与本地存储","paragraphs":["账户服务只使用登录严格所需的内容：一个在我们自己的页面间维持登录状态的必要会话 Cookie，以及保存会话刷新令牌和语言/主题偏好的浏览器本地存储。不存在任何分析、广告或跨站跟踪 Cookie。"]},{"heading":"数据共享对象","paragraphs":["我们仅与运行本服务的数据处理者共享个人数据，且仅限必要范围："],"bullets":["Google（Google 登录）和 Apple（Apple 登录）——仅当您选择使用它们登录时；相关交换受其各自隐私政策约束。","我们的邮件发送服务商 [EMAIL DELIVERY PROVIDER]，用于发送上述服务邮件。","我们的托管服务商 [HOSTING PROVIDER]，负责存储服务数据。","公共机关——仅在有效的法律要求强制我们时。"]},{"heading":"跨境传输","paragraphs":["本服务托管于 [HOSTING COUNTRY]。个人数据传出土耳其时，依照 KVKK 第 9 条进行：存在个人数据保护委员会充分性决定的，依据该决定；否则依据该条规定的适当保障措施（例如委员会发布的标准合同，并按要求向监管机构备案）。数据传出欧洲经济区或英国时，我们另行依据充分性决定或欧盟委员会的标准合同条款。下述安全措施在任何情况下均适用。"]},{"heading":"我们如何保护数据","paragraphs":["安全防护是分层的，适用于每一个账户："],"bullets":["密码使用 Argon2id 哈希；验证码仅以哈希存储；重置链接仅以 HMAC 摘要存储。","您的电话号码、两步验证密钥和 Apple 撤销令牌均使用您账户专属密钥以 AES-256-GCM 加密。","所有流量传输均加密（TLS）。登录受速率限制和账户锁定保护；会话可随时撤销，且在您请求删除时全部立即撤销。","账户操作记录在审计日志中，以便发现并调查可疑活动。"]}],"retention":{"heading":"数据保存期限","intro":"个人数据的保存不超过目的所需。以下期限由系统自动执行，而非人工审查：","columns":["数据","保存期限","期满处理"],"rows":[{"category":"账户与个人资料数据","retention":"直至您删除账户（另加 {{graceDays}} 天恢复期）","detail":"通过下文所述的分阶段删除流程永久销毁。"},{"category":"密码哈希与两步验证密钥","retention":"直至账户删除","detail":"仅以哈希或加密形式存储；随账户一并销毁。"},{"category":"会话与令牌","retention":"直至过期或退出登录","detail":"在请求删除时全部立即撤销。"},{"category":"登录尝试记录（含 IP 地址）","retention":"{{loginAttemptRetentionDays}} 天","detail":"自动清除；账户删除时立即去标识化。"},{"category":"安全审计日志","retention":"账户删除时去标识化","detail":"移除所有个人字段；删除已执行的事实（仅事件类型和时间戳）作为法律证据保留至少 3 年。"},{"category":"已发送服务邮件的记录","retention":"{{outboxRetentionDays}} 天","detail":"自动清除。"},{"category":"删除验证码","retention":"{{otpValidityMinutes}} 分钟（验证码有效期）","detail":"仅以哈希存储；过期条目由每日清理任务删除。"},{"category":"删除记录（哈希化标识符）","retention":"永久","detail":"被删除邮箱和用户名的单向 HMAC 摘要，保留的目的是确保这些标识符永远不会被他人重新注册。不含任何可读的个人数据。"},{"category":"备份","retention":"最长 6 个月","detail":"备份轮换由托管平台的保留配置执行。除此之外，账户删除时加密字段的加密密钥即被销毁，使这些数据即便在既有备份中也永久不可读。"}]},"deletion":{"heading":"删除您的账户","paragraphs":["您可以随时请求永久删除您的账户和个人数据，无需联系任何人。请求会被立即受理，并在 {{graceDays}} 天内完成："],"bullets":["您的账户立即停用并在所有设备上退出登录；所有会话、令牌和登录授权立即撤销。","在 {{graceDays}} 天内您可以改变主意——重新登录即可恢复账户并取消删除。每一步您都会收到确认邮件。","{{graceDays}} 天期满后，删除将自动执行且不可逆：个人资料数据被抹除，安全记录被去标识化，账户专属加密密钥被销毁（加密销毁，覆盖备份），且——如果您使用 Apple 登录——将通知 Apple 撤销登录授权。","您的邮箱地址和用户名永不回收：仅留存单向摘要，因此其他任何人都永远无法注册它们。"],"button":"删除我的账户","signedInHint":"已登录？您也可以在个人资料的“账户”标签页（危险区域）中进行此操作。"},"rights":[{"heading":"您在土耳其的权利（KVKK）","paragraphs":["依据第 6698 号法律第 11 条，作为数据主体，您有权：了解您的个人数据是否被处理；请求获取相关处理信息；了解处理目的及数据是否按目的使用；知悉数据在境内外被传输给哪些第三方；请求更正不完整或不准确的数据；依据第 7 条请求删除或销毁数据；请求将更正和删除通知数据接收方；对完全由自动化系统分析产生的不利结果提出异议；以及因违法处理受到损害时请求赔偿。","申请依照《向数据控制者申请的程序与原则公报》，通过下方联系方式提出——以书面形式、通过我们的注册电子邮箱（KEP）地址（如有），或从您此前向我们登记的邮箱地址发出。我们最迟在 30 天内免费答复。若申请被拒绝或未获答复，您可向个人数据保护委员会投诉。"]},{"heading":"您在欧洲经济区和英国的权利（GDPR）","paragraphs":["您有权访问您的数据、要求更正、要求删除、限制或反对处理、获取可携带副本，并在处理基于同意时随时撤回同意。其中大多数权利您可以直接在应用内行使（编辑个人资料、删除账户）；其余请通过下方联系方式与我们联系。您还有权向您所在国家的监管机构投诉。"]},{"heading":"您在加州的权利（CCPA/CPRA）","paragraphs":["您有权知悉我们收集哪些个人信息并访问、更正、删除这些信息，且不会因行使这些权利而受到歧视。由于我们不出售或共享个人信息，且敏感个人信息仅用于提供服务，因此不存在需要选择退出的事项。经核实的请求将在 45 天内处理。您也可以委托授权代理人代您提交请求。"]},{"heading":"其他所有用户","paragraphs":["同样的控制权——访问、更正、删除以及上述应用内删除流程——面向每一位用户提供，无论您居住在哪里。"]}],"closing":[{"heading":"儿童","paragraphs":["本服务不面向儿童，16 岁以下人士不得使用。我们不会有意收集儿童数据；如果您认为有儿童创建了账户，请联系我们，我们将予以删除。"]},{"heading":"本政策的变更","paragraphs":["本政策的每次修订都带有版本号（年.月，显示在页面顶部）。如有重大变更，我们将在生效前通过邮件或应用内通知告知您。删除请求始终按照提出请求时有效的条款执行。"]},{"heading":"联系与投诉","paragraphs":["数据控制者：[LEGAL ENTITY NAME]，[REGISTERED ADDRESS]。隐私联系方式：[PRIVACY CONTACT EMAIL]。我们在 30 天内（KVKK/GDPR）或 45 天内（CCPA）答复权利请求。如对结果不满意，您可向监管机构投诉：在土耳其为个人数据保护局，在欧洲经济区/英国为您所在国的数据保护机构，在加州为加州隐私保护局或总检察长。"]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: zh';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'ur')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000006', @VersionId, N'ur', N'{"title":"رازداری کی پالیسی","effectiveDate":"28 جولائی 2026 سے نافذ","versionLabel":"ورژن","unfilledWarning":"مسودہ — ڈیٹا کنٹرولر کی تفصیلات ابھی درج نہیں کی گئیں۔ تمام خانے مکمل ہونے سے پہلے یہ صفحہ شائع نہیں کیا جانا چاہیے۔","contactDpoLabel":"ڈیٹا پروٹیکشن آفیسر","contactVerbisLabel":"VERBİS رجسٹریشن نمبر","contactKepLabel":"رجسٹرڈ ای میل (KEP)","intro":["یہ پالیسی واضح کرتی ہے کہ [LEGAL ENTITY NAME] کی اکاؤنٹ سروس کون سا ذاتی ڈیٹا جمع کرتی ہے، کیوں جمع کرتی ہے، کتنے عرصے تک محفوظ رکھتی ہے، اور اس پر آپ کے کیا حقوق ہیں — بشمول یہ کہ آپ اپنا اکاؤنٹ اور اس سے جڑی ہر چیز کیسے حذف کر سکتے ہیں۔","یہ پالیسی ترکیہ کے ذاتی ڈیٹا کے تحفظ کے قانون نمبر 6698 (KVKK) — جو ہمارا بنیادی تعمیلی فریم ورک ہے — کی دفعہ 10 کے تحت مطلع کرنے کی ذمہ داری پوری کرنے کے لیے تیار کی گئی ہے، اور یورپی یونین/EEA کے جنرل ڈیٹا پروٹیکشن ریگولیشن (GDPR) اور ترمیم شدہ کیلیفورنیا کنزیومر پرائیویسی ایکٹ (CCPA/CPRA) کے تقاضوں کے مطابق لکھی گئی ہے۔ اس پالیسی میں بیان کردہ اختیارات ہر صارف کو حاصل ہیں، خواہ وہ کہیں بھی مقیم ہو۔"],"sections":[{"heading":"ہم کون سا ڈیٹا جمع کرتے ہیں","paragraphs":["ہم صرف وہی جمع کرتے ہیں جو اکاؤنٹ سروس کے کام کرنے کے لیے ضروری ہے۔ اس سے زیادہ کبھی نہیں مانگتے، اور اختیاری خانے واضح طور پر اختیاری ہیں۔"],"bullets":["اکاؤنٹ اور پروفائل: ای میل ایڈریس، نام اور خاندانی نام، اختیاری ظاہری نام، اختیاری فون نمبر (خفیہ کاری کے ساتھ محفوظ)، اختیاری پروفائل تصویر، ترجیحی زبان، ٹائم زون اور تھیم۔","اسناد اور حفاظتی ترتیبات: آپ کا پاس ورڈ (صرف یک طرفہ Argon2id ہیش کے طور پر محفوظ — ہم اسے پڑھ نہیں سکتے)، اختیاری دو مرحلہ تصدیقی کلید اور بازیابی کوڈز (خفیہ کاری کے ساتھ محفوظ)، اور پاس ورڈ تبدیلی کی تاریخ (صرف ہیش، دوبارہ استعمال روکنے کے لیے)۔","Google یا Apple کے ذریعے سائن اِن: فراہم کنندہ کی جانب سے شیئر کردہ آپ کا شناختی نمبر، ای میل اور نام۔ Apple کے لیے ایک منسوخی ٹوکن خفیہ کاری کے ساتھ صرف اس مقصد کے لیے محفوظ کیا جاتا ہے کہ اکاؤنٹ حذف کرنے پر Apple کی سائن اِن اجازت منسوخ کی جا سکے۔","حفاظتی اور استعمال کے ریکارڈ: سائن اِن کی کوششیں (وقت، IP ایڈریس، براؤزر شناخت، نتیجہ)، فعال سیشن اور ٹوکن، اور اکاؤنٹ سے متعلق کارروائیوں کا آڈٹ لاگ۔","مراسلت: آپ کو بھیجی گئی سروس ای میلز کا ریکارڈ (تصدیقی کوڈ، حفاظتی اطلاعات، حذف کی توثیقات)۔ یک بار استعمال کے کوڈ یا سائن اِن لنک والی ای میل کا مواد ترسیل ہوتے ہی اس ریکارڈ سے ہٹا دیا جاتا ہے — ہمارے منتظمین بھی اسے نہیں پڑھ سکتے۔"]},{"heading":"ہم ڈیٹا کیوں پروسیس کرتے ہیں (قانونی بنیادیں)","paragraphs":["آپ کا ڈیٹا سروس کے فارمز اور سائن اِن کے مراحل کے ذریعے الیکٹرانک طور پر جمع کیا جاتا ہے۔ ہر مقصد KVKK کی دفعہ 5 اور GDPR کی دفعہ 6 کے مساوی قانونی بنیاد پر قائم ہے:"],"bullets":["آپ کا اکاؤنٹ فراہم کرنا — تصدیق، سیشن، پروفائل، تنظیمی رکنیت (معاہدے کی انجام دہی کے لیے ضروری: KVKK دفعہ 2/5-c؛ GDPR دفعہ 6(1)(b))۔","اکاؤنٹس کو محفوظ رکھنا — سائن اِن کوششوں کے ریکارڈ، شرح کی حد بندی، سیشن کی منسوخی، آڈٹ لاگ، دھوکہ دہی کی روک تھام (جائز مفاد: KVKK دفعہ 2/5-f؛ GDPR دفعہ 6(1)(f))۔","قانونی ذمہ داریاں پوری کرنا — اس بات کا کم از کم ثبوت محفوظ رکھنا کہ حذف کی درخواست پوری کی گئی (KVKK دفعہ 2/5-ç؛ GDPR دفعہ 6(1)(c))۔","اختیاری ڈیٹا — فون نمبر اور پروفائل تصویر صرف اس لیے پروسیس ہوتے ہیں کہ آپ نے انہیں دینا چاہا، اور آپ انہیں کسی بھی وقت ہٹا سکتے ہیں (واضح رضامندی: KVKK دفعہ 1/5؛ GDPR دفعہ 6(1)(a))۔"]},{"heading":"جو ہم نہیں کرتے","paragraphs":["ہم آپ کا ذاتی ڈیٹا فروخت نہیں کرتے اور نہ ہی سیاق و سباق کے آر پار رویّے پر مبنی اشتہارات کے لیے شیئر کرتے ہیں — CCPA کی اصطلاح میں، گزشتہ 12 مہینوں میں کوئی «فروخت» یا «اشتراک» نہیں ہوا اور نہ اس کا کوئی ارادہ ہے۔ اکاؤنٹ سروس میں کوئی اشتہاری یا فریق ثالث تجزیاتی ٹریکر نہیں چلتا، اور آپ کا ڈیٹا ایسے خودکار فیصلوں کے لیے استعمال نہیں ہوتا جن کے قانونی یا اسی درجے کے اہم اثرات ہوں۔"]},{"heading":"کوکیز اور لوکل اسٹوریج","paragraphs":["اکاؤنٹ سروس صرف وہی استعمال کرتی ہے جو سائن اِن کے لیے سختی سے درکار ہے: ایک لازمی سیشن کوکی جو ہماری اپنی صفحات پر آپ کو سائن اِن رکھتی ہے، اور براؤزر کا لوکل اسٹوریج جس میں آپ کے سیشن کا ریفریش ٹوکن اور زبان/تھیم کی ترجیحات ہوتی ہیں۔ تجزیاتی، اشتہاری یا کراس سائٹ ٹریکنگ کی کوئی کوکی موجود نہیں۔"]},{"heading":"ہم ڈیٹا کس کے ساتھ شیئر کرتے ہیں","paragraphs":["ہم ذاتی ڈیٹا صرف ان پروسیسرز کے ساتھ شیئر کرتے ہیں جو سروس چلاتے ہیں، اور صرف ضرورت کی حد تک:"],"bullets":["Google (Google سائن اِن) اور Apple (Apple سائن اِن) — صرف جب آپ ان کے ذریعے سائن اِن کرنے کا انتخاب کریں؛ یہ تبادلہ ان کی اپنی رازداری پالیسیوں کے تابع ہے۔","ہمارا ای میل ترسیل فراہم کنندہ [EMAIL DELIVERY PROVIDER] — اوپر بیان کردہ سروس ای میلز بھیجنے کے لیے۔","ہمارا ہوسٹنگ فراہم کنندہ [HOSTING PROVIDER] — جو سروس کا ڈیٹا محفوظ رکھتا ہے۔","سرکاری ادارے — صرف اسی صورت میں جب کوئی درست قانونی تقاضا ہمیں مجبور کرے۔"]},{"heading":"بین الاقوامی منتقلی","paragraphs":["سروس [HOSTING COUNTRY] میں ہوسٹ کی گئی ہے۔ ذاتی ڈیٹا ترکیہ سے باہر منتقل ہونے کی صورت میں یہ KVKK کی دفعہ 9 کے تحت ہوتا ہے: جہاں ذاتی ڈیٹا تحفظ بورڈ کا کفایت (adequacy) فیصلہ موجود ہو وہاں اس کی بنیاد پر، ورنہ اس دفعہ میں فراہم کردہ مناسب ضمانتوں (جیسے بورڈ کا معیاری معاہدہ، جس کی اتھارٹی کو حسبِ ضرورت اطلاع دی جاتی ہے) کی بنیاد پر۔ EEA یا برطانیہ سے نکلنے والے ڈیٹا کے لیے ہم مزید کفایت فیصلوں یا یورپی کمیشن کی معیاری معاہداتی شقوں پر انحصار کرتے ہیں۔ نیچے دیے گئے حفاظتی اقدامات ہر صورت میں لاگو ہوتے ہیں۔"]},{"heading":"ہم ڈیٹا کی حفاظت کیسے کرتے ہیں","paragraphs":["سیکیورٹی تہ در تہ ہے اور ہر اکاؤنٹ پر لاگو ہوتی ہے:"],"bullets":["پاس ورڈ Argon2id سے ہیش کیے جاتے ہیں؛ تصدیقی کوڈ صرف ہیش کے طور پر، اور ری سیٹ لنکس صرف HMAC ڈائجسٹ کے طور پر محفوظ ہوتے ہیں۔","آپ کا فون نمبر، دو مرحلہ تصدیقی کلید اور Apple منسوخی ٹوکن آپ کے اکاؤنٹ کی مخصوص کلید کے تحت AES-256-GCM سے خفیہ کیے جاتے ہیں۔","تمام ٹریفک ترسیل کے دوران خفیہ ہوتی ہے (TLS)۔ سائن اِن شرح کی حد بندی اور اکاؤنٹ لاک سے محفوظ ہے؛ سیشن کسی بھی وقت منسوخ کیے جا سکتے ہیں اور حذف کی درخواست پر سب فوراً منسوخ ہو جاتے ہیں۔","اکاؤنٹ کی کارروائیاں آڈٹ لاگ میں درج ہوتی ہیں تاکہ مشکوک سرگرمی کا پتہ لگا کر اس کی چھان بین کی جا سکے۔"]}],"retention":{"heading":"ہم ڈیٹا کتنے عرصے رکھتے ہیں","intro":"ہم ذاتی ڈیٹا مقصد کی ضرورت سے زیادہ عرصے نہیں رکھتے۔ یہ مدتیں دستی جائزے سے نہیں بلکہ نظام کے ذریعے خودکار طور پر نافذ ہوتی ہیں:","columns":["ڈیٹا","مدتِ حفاظت","اس کے بعد کیا ہوتا ہے"],"rows":[{"category":"اکاؤنٹ اور پروفائل ڈیٹا","retention":"اکاؤنٹ حذف کرنے تک (+ {{graceDays}} دن کی بحالی مدت)","detail":"نیچے بیان کردہ مرحلہ وار حذف کے عمل سے مستقل طور پر تلف کر دیا جاتا ہے۔"},{"category":"پاس ورڈ ہیش اور دو مرحلہ تصدیقی کلیدیں","retention":"اکاؤنٹ حذف ہونے تک","detail":"صرف ہیش یا خفیہ شکل میں محفوظ؛ اکاؤنٹ کے ساتھ تلف۔"},{"category":"سیشن اور ٹوکن","retention":"میعاد ختم ہونے یا سائن آؤٹ تک","detail":"حذف کی درخواست پر سب فوراً منسوخ۔"},{"category":"سائن اِن کوششوں کے ریکارڈ (بشمول IP ایڈریس)","retention":"{{loginAttemptRetentionDays}} دن","detail":"خودکار طور پر حذف؛ اکاؤنٹ کے حذف پر فوراً شناخت سے محروم۔"},{"category":"حفاظتی آڈٹ لاگ","retention":"اکاؤنٹ کے حذف پر شناخت سے محروم","detail":"تمام ذاتی خانے ہٹا دیے جاتے ہیں؛ حذف انجام پانے کی حقیقت (صرف واقعے کی قسم اور وقت) قانونی ثبوت کے طور پر کم از کم 3 سال محفوظ رہتی ہے۔"},{"category":"بھیجی گئی سروس ای میلز کا ریکارڈ","retention":"{{outboxRetentionDays}} دن","detail":"خودکار طور پر حذف۔"},{"category":"حذف کے تصدیقی کوڈ","retention":"{{otpValidityMinutes}} منٹ (کوڈ کی میعاد)","detail":"صرف ہیش کے طور پر محفوظ؛ میعاد ختم شدہ اندراجات روزانہ کی صفائی کے عمل سے حذف ہوتے ہیں۔"},{"category":"حذف کا ریکارڈ (ہیش شدہ شناختیں)","retention":"مستقل","detail":"حذف شدہ ای میل اور صارف نام کے یک طرفہ HMAC ڈائجسٹ، جو اس لیے رکھے جاتے ہیں کہ یہ شناختیں کبھی کوئی اور دوبارہ رجسٹر نہ کر سکے۔ کوئی قابلِ مطالعہ ذاتی ڈیٹا شامل نہیں۔"},{"category":"بیک اپ","retention":"زیادہ سے زیادہ 6 ماہ","detail":"بیک اپ کی گردش ہوسٹنگ پلیٹ فارم کی ریٹینشن ترتیبات کے ذریعے نافذ ہوتی ہے۔ اس سے الگ، اکاؤنٹ حذف ہونے پر آپ کے خفیہ شدہ خانوں کی خفیہ کاری کلید تلف کر دی جاتی ہے، جس سے وہ ڈیٹا موجودہ بیک اپس کے اندر بھی مستقل طور پر ناقابلِ مطالعہ ہو جاتا ہے۔"}]},"deletion":{"heading":"اپنا اکاؤنٹ حذف کرنا","paragraphs":["آپ کسی سے رابطہ کیے بغیر، کسی بھی وقت اپنے اکاؤنٹ اور ذاتی ڈیٹا کے مستقل حذف کی درخواست دے سکتے ہیں۔ درخواست فوراً درج ہو جاتی ہے اور {{graceDays}} دن کے اندر مکمل کی جاتی ہے:"],"bullets":["آپ کا اکاؤنٹ فوراً غیر فعال ہو جاتا ہے اور تمام آلات سے سائن آؤٹ کر دیا جاتا ہے؛ تمام سیشن، ٹوکن اور سائن اِن اجازتیں فوری منسوخ ہو جاتی ہیں۔","{{graceDays}} دن تک آپ اپنا ارادہ بدل سکتے ہیں — دوبارہ سائن اِن کرنے سے اکاؤنٹ بحال ہو جاتا ہے اور حذف منسوخ۔ ہر مرحلے پر آپ کو توثیقی ای میل ملتی ہے۔","{{graceDays}} دن کی مدت کے بعد حذف خودکار طور پر انجام پاتا ہے اور ناقابلِ واپسی ہے: پروفائل ڈیٹا مٹا دیا جاتا ہے، حفاظتی ریکارڈ شناخت سے محروم کر دیے جاتے ہیں، اکاؤنٹ کی مخصوص خفیہ کاری کلیدیں تلف کر دی جاتی ہیں (کرپٹوگرافک تلفی، جو بیک اپس کا بھی احاطہ کرتی ہے)، اور — اگر آپ Apple سائن اِن استعمال کرتے تھے — Apple کو سائن اِن اجازت منسوخ کرنے کو کہا جاتا ہے۔","آپ کا ای میل ایڈریس اور صارف نام کبھی دوبارہ استعمال میں نہیں آتے: صرف یک طرفہ ڈائجسٹ باقی رہتے ہیں، اس لیے کوئی اور انہیں کبھی رجسٹر نہیں کر سکتا۔"],"button":"میرا اکاؤنٹ حذف کریں","signedInHint":"سائن اِن ہیں؟ آپ یہ کام اپنے پروفائل کے اکاؤنٹ ٹیب (خطرے کا علاقہ) سے بھی کر سکتے ہیں۔"},"rights":[{"heading":"ترکیہ میں آپ کے حقوق (KVKK)","paragraphs":["قانون نمبر 6698 کی دفعہ 11 کے تحت، بطور متعلقہ فرد آپ کو حق حاصل ہے کہ: جانیں کہ آیا آپ کا ڈیٹا پروسیس ہو رہا ہے؛ اس پروسیسنگ سے متعلق معلومات طلب کریں؛ پروسیسنگ کا مقصد اور اس کے مطابق استعمال جانیں؛ ملک کے اندر یا باہر جن فریقِ ثالث کو ڈیٹا منتقل ہوا انہیں جانیں؛ نامکمل یا غلط ڈیٹا کی تصحیح مانگیں؛ دفعہ 7 کے تحت حذف یا تلفی مانگیں؛ تصحیح و حذف کی اطلاع وصول کنندگان کو دینے کا مطالبہ کریں؛ خالصتاً خودکار نظاموں کے تجزیے سے آپ کے خلاف نکلنے والے نتیجے پر اعتراض کریں؛ اور غیر قانونی پروسیسنگ سے نقصان کی صورت میں ازالہ طلب کریں۔","درخواستیں «ڈیٹا کنٹرولر کو درخواست دینے کے اصول و ضوابط سے متعلق ضابطہ» کے مطابق نیچے دیے گئے رابطہ ذرائع سے — تحریری طور پر، ہمارے رجسٹرڈ ای میل (KEP) پتے کے ذریعے (اگر موجود ہو)، یا اس ای میل پتے سے جو آپ پہلے ہمیں بتا چکے ہیں — دی جا سکتی ہیں۔ ہم زیادہ سے زیادہ 30 دن میں مفت جواب دیتے ہیں۔ درخواست مسترد ہونے یا جواب نہ ملنے پر آپ ذاتی ڈیٹا تحفظ بورڈ میں شکایت کر سکتے ہیں۔"]},{"heading":"EEA اور برطانیہ میں آپ کے حقوق (GDPR)","paragraphs":["آپ کو اپنے ڈیٹا تک رسائی، اس کی تصحیح، اسے مٹانے، پروسیسنگ کو محدود کرنے یا اس پر اعتراض کرنے، قابلِ منتقلی نقل حاصل کرنے، اور رضامندی پر مبنی پروسیسنگ میں کسی بھی وقت رضامندی واپس لینے کا حق حاصل ہے۔ ان میں سے بیشتر حقوق آپ براہِ راست ایپ میں استعمال کر سکتے ہیں (پروفائل کی تدوین، اکاؤنٹ کا حذف)؛ باقی کے لیے نیچے دیے گئے ذرائع سے ہم سے رابطہ کریں۔ آپ کو اپنے قومی نگران ادارے میں شکایت درج کرانے کا حق بھی حاصل ہے۔"]},{"heading":"کیلیفورنیا میں آپ کے حقوق (CCPA/CPRA)","paragraphs":["آپ کو حق حاصل ہے کہ جانیں ہم کون سی ذاتی معلومات جمع کرتے ہیں اور ان تک رسائی پائیں، انہیں درست کرائیں، حذف کرائیں، اور ان حقوق کے استعمال پر کسی امتیاز کا سامنا نہ کریں۔ چونکہ ہم ذاتی معلومات فروخت یا شیئر نہیں کرتے اور حساس ذاتی معلومات صرف سروس فراہم کرنے کے لیے استعمال کرتے ہیں، اس لیے آپٹ آؤٹ کرنے کو کچھ نہیں۔ تصدیق شدہ درخواستیں ہم 45 دن میں پوری کرتے ہیں۔ آپ اپنی جانب سے درخواست دینے کے لیے مجاز نمائندہ بھی مقرر کر سکتے ہیں۔"]},{"heading":"باقی تمام صارفین","paragraphs":["یہی اختیارات — رسائی، تصحیح، حذف اور اوپر بیان کردہ ایپ کے اندر حذف کا عمل — ہر صارف کو حاصل ہیں، آپ جہاں بھی رہتے ہوں۔"]}],"closing":[{"heading":"بچے","paragraphs":["یہ سروس بچوں کے لیے نہیں ہے اور 16 سال سے کم عمر افراد اسے استعمال نہیں کر سکتے۔ ہم جان بوجھ کر بچوں کا ڈیٹا جمع نہیں کرتے؛ اگر آپ سمجھتے ہیں کہ کسی بچے نے اکاؤنٹ بنایا ہے تو ہم سے رابطہ کریں، ہم اسے حذف کر دیں گے۔"]},{"heading":"اس پالیسی میں تبدیلیاں","paragraphs":["اس پالیسی کی ہر ترمیم ایک ورژن نمبر رکھتی ہے (سال.مہینہ، صفحے کے اوپر درج)۔ اہم تبدیلیوں کی صورت میں ہم نافذ ہونے سے پہلے آپ کو ای میل یا ایپ کے اندر اطلاع سے آگاہ کریں گے۔ حذف کی درخواستیں ہمیشہ انہی شرائط کے مطابق پوری ہوتی ہیں جو درخواست کے وقت نافذ تھیں۔"]},{"heading":"رابطہ اور شکایات","paragraphs":["ڈیٹا کنٹرولر: [LEGAL ENTITY NAME]، [REGISTERED ADDRESS]۔ رازداری رابطہ: [PRIVACY CONTACT EMAIL]۔ حقوق کی درخواستوں کا جواب ہم 30 دن (KVKK/GDPR) اور 45 دن (CCPA) کے اندر دیتے ہیں۔ نتیجے سے مطمئن نہ ہوں تو آپ نگران ادارے میں شکایت کر سکتے ہیں: ترکیہ میں ذاتی ڈیٹا تحفظ اتھارٹی، EEA/برطانیہ میں آپ کا قومی ڈیٹا تحفظ ادارہ، کیلیفورنیا میں California Privacy Protection Agency یا اٹارنی جنرل۔"]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: ur';
    END

    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyTranslations] WHERE [VersionId] = @VersionId AND [LanguageCode] = N'fa')
    BEGIN
        INSERT INTO [dbo].[PrivacyPolicyTranslations] ([Id], [VersionId], [LanguageCode], [ContentJson], [CreatedAt], [CreatedBy])
        VALUES ('47000000-0000-0000-0000-000000000007', @VersionId, N'fa', N'{"title":"سیاست حریم خصوصی","effectiveDate":"قابل اجرا از ۲۸ ژوئیه ۲۰۲۶","versionLabel":"نسخه","unfilledWarning":"پیش‌نویس — اطلاعات کنترل‌کننده داده هنوز تکمیل نشده است. تا تکمیل همه موارد، این صفحه نباید منتشر شود.","contactDpoLabel":"مسئول حفاظت از داده‌ها","contactVerbisLabel":"شماره ثبت VERBİS","contactKepLabel":"ایمیل ثبت‌شده (KEP)","intro":["این سیاست توضیح می‌دهد سرویس حساب [LEGAL ENTITY NAME] چه داده‌های شخصی‌ای گردآوری می‌کند، چرا آن‌ها را گردآوری می‌کنیم، چه مدت نگه می‌داریم و چه حقوقی بر آن‌ها دارید — از جمله اینکه چگونه حساب خود و هر آنچه به آن وابسته است را حذف کنید.","این متن همچنین تکلیف اطلاع‌رسانی مقرر در ماده ۱۰ قانون حفاظت از داده‌های شخصی ترکیه به شماره ۶۶۹۸ (KVKK) — چارچوب اصلی انطباق ما — را ادا می‌کند و مطابق مقررات عمومی حفاظت از داده اتحادیه اروپا (GDPR) و قانون حریم خصوصی مصرف‌کنندگان کالیفرنیا با اصلاحات آن (CCPA/CPRA) نگاشته شده است. اختیارات توصیف‌شده در این سیاست، فارغ از محل سکونت، در دسترس همه کاربران است."],"sections":[{"heading":"داده‌هایی که گردآوری می‌کنیم","paragraphs":["فقط آنچه را گردآوری می‌کنیم که سرویس حساب برای کارکردن به آن نیاز دارد. هرگز بیش از آن نمی‌خواهیم و موارد اختیاری به‌روشنی اختیاری‌اند."],"bullets":["حساب و نمایه: نشانی ایمیل، نام و نام خانوادگی، نام نمایشی اختیاری، شماره تلفن اختیاری (به‌صورت رمزگذاری‌شده ذخیره می‌شود)، تصویر نمایه اختیاری، زبان ترجیحی، منطقه زمانی و پوسته.","اعتبارنامه‌ها و تنظیمات امنیتی: رمز عبور شما (فقط به‌صورت هش یک‌طرفه Argon2id ذخیره می‌شود — ما نمی‌توانیم آن را بخوانیم)، کلید تأیید دومرحله‌ای و کدهای بازیابی اختیاری (رمزگذاری‌شده) و تاریخچه تغییر رمز عبور (فقط هش، برای جلوگیری از استفاده مجدد).","ورود با Google یا Apple: شناسه، ایمیل و نام شما آن‌گونه که ارائه‌دهنده به اشتراک می‌گذارد. برای Apple، یک توکن ابطال به‌صورت رمزگذاری‌شده صرفاً بدین منظور ذخیره می‌شود که هنگام حذف حساب، مجوز ورود Apple باطل شود.","سوابق امنیتی و کاربردی: تلاش‌های ورود (زمان، نشانی IP، شناسه مرورگر، نتیجه)، نشست‌ها و توکن‌های فعال و گزارش ممیزی اقدامات مربوط به حساب.","مکاتبات: سابقه ایمیل‌های خدماتی که برای شما می‌فرستیم (کدهای تأیید، اعلان‌های امنیتی، تأییدیه‌های حذف). محتوای پیام‌هایی که کد یک‌بارمصرف یا پیوند ورود دارند، به‌محض تحویل ایمیل از این سابقه حذف می‌شود — حتی مدیران ما نیز نمی‌توانند آن را بخوانند."]},{"heading":"چرا داده‌ها را پردازش می‌کنیم (مبانی قانونی)","paragraphs":["داده‌های شما به‌صورت الکترونیکی و از طریق فرم‌ها و مسیرهای ورود خود سرویس گردآوری می‌شود. هر هدف بر یک مبنای قانونی طبق ماده ۵ KVKK و معادل آن در ماده ۶ GDPR استوار است:"],"bullets":["ارائه حساب شما — احراز هویت، نشست‌ها، نمایه، عضویت سازمانی (لازمه اجرای قرارداد: KVKK ماده 5/2-c؛ GDPR ماده 6(1)(b)).","امن نگه‌داشتن حساب‌ها — سوابق تلاش ورود، محدودسازی نرخ، ابطال نشست، گزارش ممیزی، پیشگیری از تقلب (منافع مشروع: KVKK ماده 5/2-f؛ GDPR ماده 6(1)(f)).","ایفای تکالیف قانونی — نگهداری حداقل مدرک مبنی بر اجرای درخواست حذف (KVKK ماده 5/2-ç؛ GDPR ماده 6(1)(c)).","داده‌های اختیاری — شماره تلفن و تصویر نمایه فقط به این دلیل پردازش می‌شوند که خودتان خواسته‌اید و هر زمان می‌توانید حذفشان کنید (رضایت صریح: KVKK ماده 5/1؛ GDPR ماده 6(1)(a))."]},{"heading":"کارهایی که نمی‌کنیم","paragraphs":["ما داده‌های شخصی شما را نمی‌فروشیم و برای تبلیغات رفتاری میان‌بستری به اشتراک نمی‌گذاریم — به تعبیر CCPA، در ۱۲ ماه گذشته هیچ «فروش» یا «اشتراک‌گذاری» رخ نداده و برنامه‌ای هم برای آن نیست. در سرویس حساب هیچ ردیاب تبلیغاتی یا تحلیلی شخص ثالثی اجرا نمی‌شود و داده‌های شما برای تصمیم‌های خودکاری که آثار حقوقی یا آثاری با اهمیت مشابه دارند به کار نمی‌رود."]},{"heading":"کوکی‌ها و حافظه محلی","paragraphs":["سرویس حساب فقط از آنچه ورود اکیداً لازم دارد استفاده می‌کند: یک کوکی نشست ضروری که شما را در صفحات خودمان واردشده نگه می‌دارد، و حافظه محلی مرورگر که توکن تازه‌سازی نشست و ترجیحات زبان/پوسته شما را نگه می‌دارد. هیچ کوکی تحلیلی، تبلیغاتی یا ردیابی بین‌سایتی وجود ندارد."]},{"heading":"داده‌ها را با چه کسانی به اشتراک می‌گذاریم","paragraphs":["داده‌های شخصی را فقط با پردازشگرانی که سرویس را اداره می‌کنند و فقط به‌قدر نیاز به اشتراک می‌گذاریم:"],"bullets":["Google (ورود با Google) و Apple (ورود با Apple) — فقط وقتی خودتان ورود با آن‌ها را انتخاب کنید؛ این تبادل تابع سیاست حریم خصوصی خود آن‌هاست.","ارائه‌دهنده ارسال ایمیل ما، [EMAIL DELIVERY PROVIDER]، برای ارسال ایمیل‌های خدماتی که در بالا شرح داده شد.","ارائه‌دهنده میزبانی ما، [HOSTING PROVIDER]، که داده‌های سرویس را ذخیره می‌کند.","مراجع عمومی — تنها در صورتی که یک الزام قانونی معتبر ما را مکلف کند."]},{"heading":"انتقال بین‌المللی","paragraphs":["سرویس در [HOSTING COUNTRY] میزبانی می‌شود. هرگاه داده‌های شخصی از ترکیه خارج شود، این انتقال بر اساس ماده ۹ KVKK انجام می‌گیرد: در صورت وجود تصمیم کفایت هیئت حفاظت از داده‌های شخصی، بر اساس آن؛ و در غیر این صورت بر اساس تضمین‌های مناسبی که همان ماده مقرر کرده است (مانند قرارداد استاندارد هیئت، با اطلاع‌رسانی به نهاد ناظر طبق مقررات). برای داده‌هایی که از منطقه اقتصادی اروپا یا بریتانیا خارج می‌شوند، افزون بر این به تصمیم‌های کفایت یا بندهای قراردادی استاندارد کمیسیون اروپا اتکا می‌کنیم. تدابیر امنیتی زیر در هر حال اعمال می‌شود."]},{"heading":"چگونه از داده‌ها محافظت می‌کنیم","paragraphs":["امنیت لایه‌لایه است و برای هر حساب اعمال می‌شود:"],"bullets":["رمزهای عبور با Argon2id هش می‌شوند؛ کدهای تأیید فقط به‌صورت هش و پیوندهای بازنشانی فقط به‌صورت چکیده HMAC ذخیره می‌شوند.","شماره تلفن، کلید تأیید دومرحله‌ای و توکن ابطال Apple شما با AES-256-GCM و زیر کلیدی مخصوص حساب شما رمزگذاری می‌شوند.","تمام ترافیک در حین انتقال رمزگذاری می‌شود (TLS). ورود با محدودسازی نرخ و قفل حساب محافظت می‌شود؛ نشست‌ها هر لحظه قابل ابطال‌اند و با درخواست حذف، همگی بی‌درنگ باطل می‌شوند.","اقدامات حساب در گزارش ممیزی ثبت می‌شود تا فعالیت مشکوک قابل شناسایی و بررسی باشد."]}],"retention":{"heading":"داده‌ها را چه مدت نگه می‌داریم","intro":"داده‌های شخصی را بیش از آنچه هدف اقتضا می‌کند نگه نمی‌داریم. این مدت‌ها نه با بازبینی دستی، بلکه به‌طور خودکار توسط سیستم اعمال می‌شوند:","columns":["داده","مدت نگهداری","پس از آن"],"rows":[{"category":"داده‌های حساب و نمایه","retention":"تا حذف حساب توسط شما (+ مهلت بازیابی {{graceDays}} روزه)","detail":"با فرایند حذف مرحله‌ای که در ادامه شرح داده شده، برای همیشه نابود می‌شود."},{"category":"هش رمزهای عبور و کلیدهای تأیید دومرحله‌ای","retention":"تا حذف حساب","detail":"فقط به‌صورت هش یا رمزگذاری‌شده ذخیره؛ همراه حساب نابود می‌شوند."},{"category":"نشست‌ها و توکن‌ها","retention":"تا انقضا یا خروج از حساب","detail":"با درخواست حذف، همگی بی‌درنگ باطل می‌شوند."},{"category":"سوابق تلاش ورود (شامل نشانی IP)","retention":"{{loginAttemptRetentionDays}} روز","detail":"به‌طور خودکار پاک می‌شوند؛ با حذف حساب بی‌درنگ هویت‌زدایی می‌شوند."},{"category":"گزارش ممیزی امنیتی","retention":"با حذف حساب هویت‌زدایی می‌شود","detail":"همه فیلدهای شخصی حذف می‌شوند؛ اصلِ انجام‌شدن حذف (فقط نوع رویداد و مهر زمانی) به‌عنوان مدرک قانونی دست‌کم ۳ سال نگه داشته می‌شود."},{"category":"سابقه ایمیل‌های خدماتی ارسال‌شده","retention":"{{outboxRetentionDays}} روز","detail":"به‌طور خودکار پاک می‌شود."},{"category":"کدهای تأیید حذف","retention":"{{otpValidityMinutes}} دقیقه (اعتبار کد)","detail":"فقط به‌صورت هش ذخیره می‌شوند؛ ورودی‌های منقضی با کار پاک‌سازی روزانه حذف می‌شوند."},{"category":"سابقه حذف (شناسه‌های هش‌شده)","retention":"دائمی","detail":"چکیده‌های HMAC یک‌طرفه از ایمیل و نام کاربری حذف‌شده، که نگه داشته می‌شوند تا این شناسه‌ها هرگز توسط دیگری قابل ثبت مجدد نباشند. هیچ داده شخصی قابل‌خواندنی در بر ندارد."},{"category":"نسخه‌های پشتیبان","retention":"حداکثر ۶ ماه","detail":"چرخه نسخه‌های پشتیبان با پیکربندی نگهداری پلتفرم میزبانی اعمال می‌شود. مستقل از آن، با حذف حساب، کلید رمزگذاری فیلدهای رمزگذاری‌شده شما نابود می‌شود و آن داده‌ها حتی درون نسخه‌های پشتیبان موجود نیز برای همیشه غیرقابل خواندن می‌شوند."}]},"deletion":{"heading":"حذف حساب شما","paragraphs":["می‌توانید هر زمان و بدون تماس با هیچ‌کس، حذف دائمی حساب و داده‌های شخصی خود را درخواست کنید. درخواست بی‌درنگ ثبت و ظرف {{graceDays}} روز تکمیل می‌شود:"],"bullets":["حساب شما فوراً غیرفعال و از همه دستگاه‌ها خارج می‌شود؛ همه نشست‌ها، توکن‌ها و مجوزهای ورود بی‌درنگ باطل می‌شوند.","تا {{graceDays}} روز می‌توانید منصرف شوید — ورود دوباره، حساب را بازیابی و حذف را لغو می‌کند. در هر مرحله ایمیل تأیید دریافت می‌کنید.","پس از مهلت {{graceDays}} روزه، حذف به‌طور خودکار اجرا می‌شود و بازگشت‌ناپذیر است: داده‌های نمایه پاک می‌شوند، سوابق امنیتی هویت‌زدایی می‌شوند، کلیدهای رمزگذاری مخصوص حساب نابود می‌شوند (امحای رمزنگارانه، شامل نسخه‌های پشتیبان) و — اگر با Apple وارد می‌شدید — از Apple خواسته می‌شود مجوز ورود را باطل کند.","نشانی ایمیل و نام کاربری شما هرگز دوباره به کار گرفته نمی‌شوند: فقط چکیده‌های یک‌طرفه باقی می‌مانند، پس هیچ‌کس دیگر هرگز نمی‌تواند آن‌ها را ثبت کند."],"button":"حذف حساب من","signedInHint":"وارد شده‌اید؟ این کار را از زبانه «حساب» در نمایه خود (منطقه خطر) نیز می‌توانید انجام دهید."},"rights":[{"heading":"حقوق شما در ترکیه (KVKK)","paragraphs":["بر اساس ماده ۱۱ قانون شماره ۶۶۹۸، شما به‌عنوان شخص موضوع داده حق دارید: بدانید داده‌های شخصی‌تان پردازش می‌شود یا نه؛ درباره آن پردازش اطلاعات بخواهید؛ هدف پردازش و مطابقت استفاده با آن هدف را بدانید؛ اشخاص ثالثی را که داده‌ها در داخل یا خارج کشور به آن‌ها منتقل شده بشناسید؛ اصلاح داده‌های ناقص یا نادرست را بخواهید؛ بر پایه ماده ۷ حذف یا امحای داده‌ها را بخواهید؛ بخواهید اصلاح‌ها و حذف‌ها به گیرندگان داده اطلاع داده شود؛ به نتیجه‌ای که صرفاً از تحلیل با سامانه‌های خودکار به زیان شما پدید آید اعتراض کنید؛ و در صورت زیان ناشی از پردازش غیرقانونی، جبران خسارت مطالبه کنید.","درخواست‌ها مطابق «ابلاغیه اصول و رویه‌های مراجعه به کنترل‌کننده داده» از راه‌های تماس زیر — به‌صورت کتبی، از طریق نشانی ایمیل ثبت‌شده (KEP) ما در صورت وجود، یا از نشانی ایمیلی که قبلاً به ما اعلام کرده‌اید — قابل ارائه است. حداکثر ظرف ۳۰ روز و به‌رایگان پاسخ می‌دهیم. اگر درخواست رد شود یا بی‌پاسخ بماند، می‌توانید به هیئت حفاظت از داده‌های شخصی شکایت کنید."]},{"heading":"حقوق شما در منطقه اقتصادی اروپا و بریتانیا (GDPR)","paragraphs":["شما حق دارید به داده‌های خود دسترسی یابید، اصلاحشان را بخواهید، پاک‌شدنشان را بخواهید، پردازش را محدود کنید یا به آن اعتراض کنید، نسخه‌ای قابل‌انتقال دریافت کنید و در پردازش مبتنی بر رضایت، هر زمان رضایت خود را پس بگیرید. بیشتر این حقوق را می‌توانید مستقیماً در برنامه اعمال کنید (ویرایش نمایه، حذف حساب)؛ برای بقیه با راه‌های تماس زیر با ما تماس بگیرید. همچنین حق دارید نزد نهاد نظارتی ملی خود شکایت ثبت کنید."]},{"heading":"حقوق شما در کالیفرنیا (CCPA/CPRA)","paragraphs":["شما حق دارید بدانید چه اطلاعات شخصی‌ای گردآوری می‌کنیم و به آن دسترسی یابید، اصلاحش کنید، حذفش کنید و به‌خاطر اعمال این حقوق با تبعیض روبه‌رو نشوید. چون اطلاعات شخصی را نمی‌فروشیم و به اشتراک نمی‌گذاریم و اطلاعات شخصی حساس را فقط برای ارائه سرویس به کار می‌بریم، چیزی برای انصراف وجود ندارد. درخواست‌های تأییدشده را ظرف ۴۵ روز اجابت می‌کنیم. می‌توانید درخواست را از طریق نماینده مجاز نیز از سوی خود ارسال کنید."]},{"heading":"سایر کاربران","paragraphs":["همین اختیارات — دسترسی، اصلاح، حذف و مسیر حذف درون‌برنامه‌ای بالا — در اختیار همه کاربران است، هر جا که زندگی کنید."]}],"closing":[{"heading":"کودکان","paragraphs":["این سرویس برای کودکان نیست و افراد زیر ۱۶ سال مجاز به استفاده از آن نیستند. ما آگاهانه داده کودکان را گردآوری نمی‌کنیم؛ اگر گمان می‌کنید کودکی حسابی ساخته است، با ما تماس بگیرید تا آن را حذف کنیم."]},{"heading":"تغییرات این سیاست","paragraphs":["هر بازنگری این سیاست شماره نسخه‌ای دارد (سال.ماه، در بالای صفحه). در صورت تغییرات اساسی، پیش از اجرا از طریق ایمیل یا اعلان درون‌برنامه به شما اطلاع می‌دهیم. درخواست‌های حذف همیشه بر پایه شرایطی اجرا می‌شوند که در زمان ثبت درخواست حاکم بوده است."]},{"heading":"تماس و شکایت","paragraphs":["کنترل‌کننده داده: [LEGAL ENTITY NAME]، [REGISTERED ADDRESS]. تماس حریم خصوصی: [PRIVACY CONTACT EMAIL]. به درخواست‌های حقوقی ظرف ۳۰ روز (KVKK/GDPR) و ۴۵ روز (CCPA) پاسخ می‌دهیم. اگر از نتیجه راضی نبودید، می‌توانید به نهاد نظارتی مربوط شکایت کنید: در ترکیه نهاد حفاظت از داده‌های شخصی، در منطقه اقتصادی اروپا/بریتانیا نهاد ملی حفاظت از داده شما، و در کالیفرنیا California Privacy Protection Agency یا دادستان کل."]}]}', GETUTCDATE(), @SystemUserId);
        PRINT 'Created privacy policy content: fa';
    END

    -- Publish the seeded revision so the public page has content on a fresh
    -- install (idempotent: only when nothing is published yet).
    IF NOT EXISTS (SELECT 1 FROM [dbo].[PrivacyPolicyVersions] WHERE [IsPublished] = 1)
    BEGIN
        UPDATE [dbo].[PrivacyPolicyVersions] SET [IsPublished] = 1 WHERE [Id] = @VersionId;
        PRINT 'Published privacy policy version 2026.07';
    END
END
GO
